{"command":"mkdir -p /tmp/tc3; cd /tmp/tc3; truncate -s 1000000 max; for p in 11 12 125 13 14 15 20 24 25 26 30 33 34; do truncate -s $((p*1000000/100)) p$p; done; truncate -s 125000 p125; cd /workspace; ./executable index -d /tmp/tc3.db /tmp/tc3; cat > /tmp/tools/pty.py <<'EOF'
import pty, os, sys, fcntl, termios, struct
def run(args, cols=80, rows=24, env=None):
    pid, fd = pty.fork()
    if pid == 0:
        if env:
            os.environ.update(env)
        os.execv(args[0], args)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out=b''
    while True:
        try:
            d=os.read(fd, 65536)
        except OSError: break
        if not d: break
        out+=d
    os.waitpid(pid,0)
    return out
if __name__ == '__main__':
    cols = int(sys.argv[1])
    o = run(sys.argv[2:], cols=cols)
    for l in o.decode().split('\r\n'): print(repr(l))
EOF
python3 /tmp/tools/pty.py 80 ./executable ls -cab -d /tmp/tc3.db /tmp/tc3; python3 /tmp/tools/pty.py 60 ./executable ls -cabg -d /tmp/tc3.db /tmp/tc3 | head -3"}

