#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include "buffer.h"

struct buffer *buffer_new(void *data, size_t len)
{
	struct buffer *b = calloc(1, sizeof *b);
	if (data) {
		b->data = data;
		b->len = len;
		b->max = len;
	} else {
		b->max = 1024;
		b->data = malloc(b->max);
	}
	return b;
}

void buffer_free(struct buffer *b)
{
	if (!b) return;
	free(b->data);
	free(b);
}

static void buffer_grow(struct buffer *b, size_t need)
{
	if (b->len + need <= b->max) return;
	while (b->len + need > b->max) b->max *= 2;
	b->data = realloc(b->data, b->max);
}

void buffer_put(struct buffer *b, const void *data, size_t len)
{
	buffer_grow(b, len);
	memcpy(b->data + b->len, data, len);
	b->len += len;
}

/* SQLite4-style variable length integer encoding */
void buffer_put_varint(struct buffer *b, uint64_t v)
{
	uint8_t buf[9];
	size_t n;
	if (v <= 240) {
		buf[0] = v; n = 1;
	} else if (v <= 2287) {
		buf[0] = (v - 240) / 256 + 241;
		buf[1] = (v - 240) % 256;
		n = 2;
	} else if (v <= 67823) {
		buf[0] = 249;
		buf[1] = (v - 2288) / 256;
		buf[2] = (v - 2288) % 256;
		n = 3;
	} else {
		int bytes = 3;
		uint64_t t = v >> 24;
		while (t) { bytes++; t >>= 8; }
		buf[0] = 247 + bytes;
		for (int i = 0; i < bytes; i++) {
			buf[1 + i] = (v >> (8 * (bytes - 1 - i))) & 0xff;
		}
		n = 1 + bytes;
	}
	buffer_put(b, buf, n);
}

void buffer_put_string(struct buffer *b, const char *s)
{
	size_t l = strlen(s);
	buffer_put_varint(b, l);
	buffer_put(b, s, l);
}

size_t buffer_get(struct buffer *b, void *data, size_t len)
{
	if (b->ptr + len > b->len) len = b->len - b->ptr;
	memcpy(data, b->data + b->ptr, len);
	b->ptr += len;
	return len;
}

int buffer_get_varint(struct buffer *b, uint64_t *v)
{
	if (b->ptr >= b->len) return -1;
	uint8_t a0 = b->data[b->ptr];
	if (a0 <= 240) {
		*v = a0;
		b->ptr += 1;
		return 0;
	}
	if (a0 <= 248) {
		if (b->ptr + 2 > b->len) return -1;
		*v = 240 + 256 * (uint64_t)(a0 - 241) + b->data[b->ptr + 1];
		b->ptr += 2;
		return 0;
	}
	if (a0 == 249) {
		if (b->ptr + 3 > b->len) return -1;
		*v = 2288 + 256 * (uint64_t)b->data[b->ptr + 1] + b->data[b->ptr + 2];
		b->ptr += 3;
		return 0;
	}
	int bytes = a0 - 247;
	if (b->ptr + 1 + bytes > b->len) return -1;
	uint64_t r = 0;
	for (int i = 0; i < bytes; i++) r = (r << 8) | b->data[b->ptr + 1 + i];
	*v = r;
	b->ptr += 1 + bytes;
	return 0;
}

int buffer_get_string(struct buffer *b, char **s)
{
	uint64_t l;
	if (buffer_get_varint(b, &l) < 0) return -1;
	if (b->ptr + l > b->len) return -1;
	char *r = malloc(l + 1);
	memcpy(r, b->data + b->ptr, l);
	r[l] = '\0';
	b->ptr += l;
	*s = r;
	return 0;
}

void buffer_seek(struct buffer *b, size_t off)
{
	b->ptr = off;
}

size_t buffer_remaining(struct buffer *b)
{
	return b->len > b->ptr ? b->len - b->ptr : 0;
}
