#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sqlite3.h>
#include <sys/stat.h>
#include <fcntl.h>

#include "db.h"

struct db {
	sqlite3 *s;
	sqlite3_stmt *stmt_get;
	sqlite3_stmt *stmt_put;
	int writable;
	int in_txn;
};

static const char *db_type_check(const char *path)
{
	char buf[64];
	memset(buf, 0, sizeof buf);
	int fd = open(path, O_RDONLY);
	if (fd < 0) return "_unknown_";
	ssize_t n = read(fd, buf, sizeof buf);
	close(fd);
	if (n >= 16 && memcmp(buf, "SQLite format 3", 15) == 0) return "sqlite3";
	if (n >= 13 && memcmp(buf, "ToKyO CaBiNeT", 13) == 0) return "tokyocabinet";
	if (n >= 3 && memcmp(buf, "KC\n", 3) == 0) return "kyotocabinet";
	if (n >= 20 && (unsigned char)buf[16] == 0xde && (unsigned char)buf[17] == 0xc0 &&
	    (unsigned char)buf[18] == 0xef && (unsigned char)buf[19] == 0xbe) return "lmdb";
	return "_unknown_";
}

static int prepare(struct db *db, const char *sql, sqlite3_stmt **st)
{
	return sqlite3_prepare_v2(db->s, sql, -1, st, NULL);
}

struct db *db_open(const char *path_db, int flags, duc_errno *e)
{
	struct db *db = calloc(1, sizeof *db);
	int rc;
	int oflags;

	if (flags & DUC_OPEN_RW) {
		oflags = SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE;
		db->writable = 1;
	} else {
		oflags = SQLITE_OPEN_READONLY;
	}

	rc = sqlite3_open_v2(path_db, &db->s, oflags, NULL);
	if (rc != SQLITE_OK) {
		*e = DUC_E_DB_NOT_FOUND;
		if (db->s) sqlite3_close(db->s);
		free(db);
		return NULL;
	}

	if (db->writable) {
		char *err = NULL;
		rc = sqlite3_exec(db->s, "CREATE TABLE IF NOT EXISTS blobs(key unique primary key, value)", NULL, NULL, &err);
		if (rc != SQLITE_OK) {
			sqlite3_free(err);
			if (rc == SQLITE_NOTADB || rc == SQLITE_CORRUPT) {
				*e = DUC_E_DB_CORRUPT;
			} else if (rc == SQLITE_CANTOPEN || rc == SQLITE_READONLY) {
				*e = DUC_E_DB_NOT_FOUND;
			} else {
				*e = DUC_E_DB_CORRUPT;
			}
			sqlite3_close(db->s);
			free(db);
			return NULL;
		}
		sqlite3_exec(db->s, "CREATE INDEX IF NOT EXISTS keys on blobs(key)", NULL, NULL, NULL);
		sqlite3_exec(db->s, "PRAGMA synchronous = OFF", NULL, NULL, NULL);
		sqlite3_exec(db->s, "PRAGMA journal_mode = DELETE", NULL, NULL, NULL);
		rc = prepare(db, "INSERT OR REPLACE INTO blobs(key, value) VALUES(?, ?)", &db->stmt_put);
		if (rc != SQLITE_OK) {
			*e = DUC_E_DB_CORRUPT;
			sqlite3_close(db->s);
			free(db);
			return NULL;
		}
	}

	rc = prepare(db, "SELECT value FROM blobs WHERE key = ?", &db->stmt_get);
	if (rc != SQLITE_OK) {
		if (rc == SQLITE_NOTADB || rc == SQLITE_CORRUPT) {
			*e = DUC_E_DB_CORRUPT;
			if (db->stmt_put) sqlite3_finalize(db->stmt_put);
			sqlite3_close(db->s);
			free(db);
			return NULL;
		}
		/* Probably no such table: check the database type */
		const char *type = db_type_check(path_db);
		if (strcmp(type, DUC_DB_BACKEND) != 0) {
			*e = DUC_E_DB_TYPE_MISMATCH;
			fprintf(stderr, "Error opening: %s - unsupported DB type %s, duc compiled for %s\n",
				path_db, type, DUC_DB_BACKEND);
			if (db->stmt_put) sqlite3_finalize(db->stmt_put);
			sqlite3_close(db->s);
			free(db);
			return NULL;
		}
		db->stmt_get = NULL;
	}

	return db;
}

void db_close(struct db *db)
{
	if (!db) return;
	if (db->in_txn) db_commit(db);
	if (db->stmt_get) sqlite3_finalize(db->stmt_get);
	if (db->stmt_put) sqlite3_finalize(db->stmt_put);
	sqlite3_close(db->s);
	free(db);
}

int db_begin(struct db *db)
{
	if (!db->writable || db->in_txn) return 0;
	int rc = sqlite3_exec(db->s, "BEGIN TRANSACTION", NULL, NULL, NULL);
	if (rc == SQLITE_OK) db->in_txn = 1;
	return rc == SQLITE_OK ? 0 : -1;
}

int db_commit(struct db *db)
{
	if (!db->in_txn) return 0;
	db->in_txn = 0;
	int rc = sqlite3_exec(db->s, "COMMIT", NULL, NULL, NULL);
	return rc == SQLITE_OK ? 0 : -1;
}

int db_put(struct db *db, const void *key, size_t key_len, const void *val, size_t val_len)
{
	if (!db->stmt_put) return -1;
	sqlite3_reset(db->stmt_put);
	sqlite3_bind_text(db->stmt_put, 1, key, key_len, SQLITE_STATIC);
	sqlite3_bind_blob(db->stmt_put, 2, val, val_len, SQLITE_STATIC);
	int rc = sqlite3_step(db->stmt_put);
	sqlite3_reset(db->stmt_put);
	return rc == SQLITE_DONE ? 0 : -1;
}

void *db_get(struct db *db, const void *key, size_t key_len, size_t *val_len)
{
	if (!db->stmt_get) return NULL;
	sqlite3_reset(db->stmt_get);
	sqlite3_bind_text(db->stmt_get, 1, key, key_len, SQLITE_STATIC);
	int rc = sqlite3_step(db->stmt_get);
	void *r = NULL;
	if (rc == SQLITE_ROW) {
		const void *p = sqlite3_column_blob(db->stmt_get, 0);
		int n = sqlite3_column_bytes(db->stmt_get, 0);
		r = malloc(n + 1);
		if (n > 0) memcpy(r, p, n);
		((char *)r)[n] = 0;
		*val_len = n;
	}
	sqlite3_reset(db->stmt_get);
	return r;
}
