/*
 * Canonicalize a path: make absolute using the cwd, resolve "." and ".."
 * components and collapse multiple slashes. Symlinks are not resolved.
 */
char *duc_canonicalize_path(const char *path)
{
	char *abs;
	if (path[0] == '/') {
		abs = strdup(path);
	} else {
		char cwd[PATH_MAX];
		if (getcwd(cwd, sizeof cwd) == NULL) strcpy(cwd, "/");
		size_t l = strlen(cwd) + 1 + strlen(path) + 1;
		abs = malloc(l);
		snprintf(abs, l, "%s/%s", cwd, path);
	}

	/* split in components */
	size_t n = 0;
	char **parts = malloc(sizeof(char *) * (strlen(abs) / 1 + 2));
	char *saveptr = NULL;
	char *tok = strtok_r(abs, "/", &saveptr);
	while (tok) {
		if (strcmp(tok, ".") == 0) {
			/* skip */
		} else if (strcmp(tok, "..") == 0) {
			if (n > 0) n--;
		} else {
			parts[n++] = tok;
		}
		tok = strtok_r(NULL, "/", &saveptr);
	}

	size_t len = 1;
	for (size_t i = 0; i < n; i++) len += strlen(parts[i]) + 1;
	char *out = malloc(len + 1);
	char *p = out;
	if (n == 0) {
		strcpy(out, "/");
	} else {
		*p = 0;
		for (size_t i = 0; i < n; i++) {
			*p++ = '/';
			size_t l = strlen(parts[i]);
			memcpy(p, parts[i], l);
			p += l;
		}
		*p = 0;
	}
	free(parts);
	free(abs);
	return out;
}

