	uint64_t v;
	int ok = 1;

	if (buffer_get_string(b, &rep->path) < 0) ok = 0;
	if (ok && buffer_get_varint(b, &v) == 0) rep->devino.dev = v; else ok = 0;
	if (ok && buffer_get_varint(b, &v) == 0) rep->devino.ino = v; else ok = 0;
	if (ok && buffer_get_varint(b, &v) == 0) rep->time_start.tv_sec = v; else ok = 0;
	if (ok && buffer_get_varint(b, &v) == 0) rep->time_start.tv_usec = v; else ok = 0;
