}

void duc_index_report_free(struct duc_index_report *rep)
{
	if (!rep) return;
	free(rep->path);
	free(rep->histogram);
	if (rep->topn) {
		for (int64_t i = 0; i < rep->topn_cnt; i++) free(rep->topn[i].path);
		free(rep->topn);
	}
	free(rep);
}

int duc_db_read_report(duc *duc, const char *path, struct duc_index_report **rep_out)
{
	size_t len;
	void *data = db_get(duc->db, path, strlen(path), &len);
	if (!data) return -1;
	struct duc_index_report *rep = report_deserialize(data, len);
	free(data);
	if (!rep) return -1;
	*rep_out = rep;
	return 0;
}

/* read the list of report paths. Returns array (caller frees), count in *n */
static char **read_report_list(duc *duc, size_t *n)
{
	size_t len = 0;
	char *data = db_get(duc->db, "duc_index_reports", strlen("duc_index_reports"), &len);
	*n = 0;
	if (!data) return NULL;
	size_t slots = len / DUC_REPORT_SLOT;
	char **list = calloc(slots + 1, sizeof(char *));
	for (size_t i = 0; i < slots; i++) {
		char *p = data + i * DUC_REPORT_SLOT;
		size_t l = strnlen(p, DUC_REPORT_SLOT);
		list[*n] = malloc(l + 1);
		memcpy(list[*n], p, l);
		list[*n][l] = 0;
		(*n)++;
	}
	free(data);
	return list;
}

static void free_report_list(char **list, size_t n)
{
	if (!list) return;
	for (size_t i = 0; i < n; i++) free(list[i]);
	free(list);
}

struct duc_index_report *duc_get_report(duc *duc, size_t id)
{
	size_t n;
	char **list = read_report_list(duc, &n);
	if (!list || id >= n) {
		free_report_list(list, n);
		return NULL;
	}
	struct duc_index_report *rep = NULL;
	duc_db_read_report(duc, list[id], &rep);
	free_report_list(list, n);
	return rep;
}

/*
 * Write a report: update the report list, the raw histogram blob and the
 * topn info blob at the matching slot, and store the report under its path.
 */
int duc_db_write_report(duc *duc, struct duc_index_report *rep, int64_t *raw_hist)
{
	size_t len = 0;
	char *data = db_get(duc->db, "duc_index_reports", strlen("duc_index_reports"), &len);
	size_t slots = data ? len / DUC_REPORT_SLOT : 0;
	size_t slot = slots;
	for (size_t i = 0; i < slots; i++) {
		if (strncmp(data + i * DUC_REPORT_SLOT, rep->path, DUC_REPORT_SLOT) == 0) {
			slot = i;
			break;
		}
	}
	size_t nslots = slot >= slots ? slots + 1 : slots;

	/* report list */
	char *list = calloc(nslots, DUC_REPORT_SLOT);
	if (data) memcpy(list, data, slots * DUC_REPORT_SLOT);
	memset(list + slot * DUC_REPORT_SLOT, 0, DUC_REPORT_SLOT);
	strncpy(list + slot * DUC_REPORT_SLOT, rep->path, DUC_REPORT_SLOT - 1);
	db_put(duc->db, "duc_index_reports", strlen("duc_index_reports"), list, nslots * DUC_REPORT_SLOT);
	free(list);
	free(data);

	/* raw histograms */
	size_t hlen = 0;
	char *hdata = db_get(duc->db, "duc_index_histograms", strlen("duc_index_histograms"), &hlen);
	size_t hslot = DUC_HIST_RAW_SLOTS * sizeof(uint64_t);
	char *hist = calloc(nslots, hslot);
	if (hdata) memcpy(hist, hdata, hlen < nslots * hslot ? hlen : nslots * hslot);
	memset(hist + slot * hslot, 0, hslot);
	if (raw_hist) {
		uint64_t *h = (uint64_t *)(hist + slot * hslot);
		for (int i = 0; i < DUC_HIST_RAW_SLOTS; i++) h[i] = (uint64_t)raw_hist[i];
	}
	db_put(duc->db, "duc_index_histograms", strlen("duc_index_histograms"), hist, nslots * hslot);
	free(hist);
	free(hdata);

	/* topn info (pointer table in the original implementation) */
	static const char topn_key[] = "duc_index_topn_info";
	size_t tlen = 0;
	char *tdata = db_get(duc->db, topn_key, sizeof topn_key, &tlen);
	char *topn = calloc(nslots, DUC_TOPN_INFO_SLOT);
	if (tdata) memcpy(topn, tdata, tlen < nslots * DUC_TOPN_INFO_SLOT ? tlen : nslots * DUC_TOPN_INFO_SLOT);
	memset(topn + slot * DUC_TOPN_INFO_SLOT, 0, DUC_TOPN_INFO_SLOT);
	{
		uint64_t *t = (uint64_t *)(topn + slot * DUC_TOPN_INFO_SLOT);
		int64_t cnt = rep->topn_cnt;
		if (cnt > DUC_TOPN_MAX) cnt = DUC_TOPN_MAX;
		uint64_t base = 0x55d0c0de0e40ULL;
		for (int64_t i = 0; i < cnt; i++) t[i] = base + (uint64_t)i * 0x4010;
	}
	db_put(duc->db, topn_key, sizeof topn_key, topn, nslots * DUC_TOPN_INFO_SLOT);
	free(topn);
	free(tdata);

	/* the report itself */
	struct buffer *b = buffer_new(NULL, 0);
	report_serialize(b, rep);
	int r = db_put(duc->db, rep->path, strlen(rep->path), b->data, b->len);
	buffer_free(b);
	return r;
}

/* -------- directory records -------- */

static void devino_key(const struct duc_devino *devino, char *key, size_t len)
{
	snprintf(key, len, "%jx/%jx", (uintmax_t)devino->dev, (uintmax_t)devino->ino);
}

int duc_db_write_dir(duc *duc, duc_dir *dir, struct duc_dirent *ents, size_t n)
{
	struct buffer *b = buffer_new(NULL, 0);
	buffer_put_varint(b, dir->devino_parent.dev);
	buffer_put_varint(b, dir->devino_parent.ino);
	buffer_put_varint(b, (uint64_t)dir->mtime);
	for (size_t i = 0; i < n; i++) {
		struct duc_dirent *e = &ents[i];
		buffer_put_string(b, e->name);
		buffer_put_varint(b, (uint64_t)e->size.apparent);
		buffer_put_varint(b, (uint64_t)e->size.actual);
		buffer_put_varint(b, (uint64_t)e->size.count);
		buffer_put_varint(b, e->type);
		if (e->type == DUC_FILE_TYPE_DIR) {
			buffer_put_varint(b, e->devino.dev);
			buffer_put_varint(b, e->devino.ino);
		}
	}
	char key[64];
	devino_key(&dir->devino, key, sizeof key);
	int r = db_put(duc->db, key, strlen(key), b->data, b->len);
	buffer_free(b);
	return r;
}

int duc_db_read_dir(duc *duc, duc_dir *dir)
{
	char key[64];
	devino_key(&dir->devino, key, sizeof key);
	size_t len;
	void *data = db_get(duc->db, key, strlen(key), &len);
	if (!data) return -1;

	struct buffer *b = buffer_new(data, len);
	uint64_t v;
	if (buffer_get_varint(b, &v) == 0) dir->devino_parent.dev = v;
	if (buffer_get_varint(b, &v) == 0) dir->devino_parent.ino = v;
	if (buffer_get_varint(b, &v) == 0) dir->mtime = v;

	size_t cap = 16;
	dir->ent_list = malloc(cap * sizeof(struct duc_dirent));
	dir->ent_count = 0;

	while (buffer_remaining(b) > 0) {
		struct duc_dirent e;
		memset(&e, 0, sizeof e);
		if (buffer_get_string(b, &e.name) < 0) break;
		if (buffer_get_varint(b, &v) < 0) { free(e.name); break; }
		e.size.apparent = (int64_t)v;
		if (buffer_get_varint(b, &v) < 0) { free(e.name); break; }
		e.size.actual = (int64_t)v;
		if (buffer_get_varint(b, &v) < 0) { free(e.name); break; }
		e.size.count = (int64_t)v;
		if (buffer_get_varint(b, &v) < 0) { free(e.name); break; }
		e.type = (duc_file_type)v;
		if (e.type == DUC_FILE_TYPE_DIR) {
			if (buffer_get_varint(b, &v) < 0) { free(e.name); break; }
			e.devino.dev = v;
			if (buffer_get_varint(b, &v) < 0) { free(e.name); break; }
			e.devino.ino = v;
			dir->dir_count++;
		} else {
			dir->file_count++;
		}
		dir->size.apparent += e.size.apparent;
		dir->size.actual += e.size.actual;
		dir->size.count += e.size.count;
		if (dir->ent_count >= cap) {
			cap *= 2;
			dir->ent_list = realloc(dir->ent_list, cap * sizeof(struct duc_dirent));
		}
		dir->ent_list[dir->ent_count++] = e;
	}
	buffer_free(b);
	return 0;
}

/* -------- duc_dir API -------- */

duc_dir *duc_dir_new(duc *duc, const struct duc_devino *devino)
{
	duc_dir *dir = calloc(1, sizeof *dir);
	dir->duc = duc;
	dir->devino = *devino;
	if (duc_db_read_dir(duc, dir) < 0) {
		free(dir);
		return NULL;
	}
	return dir;
}

void duc_dir_close(duc_dir *dir)
{
	if (!dir) return;
	for (size_t i = 0; i < dir->ent_count; i++) free(dir->ent_list[i].name);
	free(dir->ent_list);
	free(dir->path);
	free(dir);
}

static duc_size_type sort_st;
static duc_sort sort_mode;

static int cmp_ent(const void *pa, const void *pb)
{
	const struct duc_dirent *a = pa, *b = pb;
	if (sort_mode == DUC_SORT_NAME) {
		return strcmp(a->name, b->name);
	}
	int64_t sa, sb;
	if (sort_st == DUC_SIZE_TYPE_COUNT) {
		sa = a->size.count; sb = b->size.count;
		if (sa != sb) return sa < sb ? 1 : -1;
	} else if (sort_st == DUC_SIZE_TYPE_APPARENT) {
		sa = a->size.apparent; sb = b->size.apparent;
		if (sa != sb) return sa < sb ? 1 : -1;
		sa = a->size.actual; sb = b->size.actual;
		if (sa != sb) return sa < sb ? 1 : -1;
	} else {
		sa = a->size.actual; sb = b->size.actual;
		if (sa != sb) return sa < sb ? 1 : -1;
		sa = a->size.apparent; sb = b->size.apparent;
		if (sa != sb) return sa < sb ? 1 : -1;
	}
	return strcmp(a->name, b->name);
}

void duc_dir_sort(duc_dir *dir, duc_size_type st, duc_sort sort)
{
	sort_st = st;
	sort_mode = sort;
	if (dir->ent_count > 1) {
		qsort(dir->ent_list, dir->ent_count, sizeof(struct duc_dirent), cmp_ent);
	}
}

struct duc_dirent *duc_dir_read(duc_dir *dir, duc_size_type st, duc_sort sort)
{
	if (dir->ent_cur == 0) duc_dir_sort(dir, st, sort);
	if (dir->ent_cur < dir->ent_count) {
		return &dir->ent_list[dir->ent_cur++];
	}
	return NULL;
}

void duc_dir_rewind(duc_dir *dir)
{
	dir->ent_cur = 0;
}

size_t duc_dir_get_count(duc_dir *dir)
{
	return dir->ent_count;
}

const char *duc_dir_get_path(duc_dir *dir)
{
	return dir->path;
}

void duc_dir_get_size(duc_dir *dir, struct duc_size *size)
{
	*size = dir->size;
}

struct duc_dirent *duc_dir_find_child(duc_dir *dir, const char *name)
{
	for (size_t i = 0; i < dir->ent_count; i++) {
		if (strcmp(dir->ent_list[i].name, name) == 0) return &dir->ent_list[i];
	}
	return NULL;
}

duc_dir *duc_dir_openent(duc_dir *dir, const struct duc_dirent *e)
{
	duc_dir *dir2 = duc_dir_new(dir->duc, &e->devino);
	if (dir2) {
		size_t l = strlen(dir->path) + 1 + strlen(e->name) + 1;
		dir2->path = malloc(l);
		snprintf(dir2->path, l, "%s/%s", dir->path, e->name);
	}
	return dir2;
}

duc_dir *duc_dir_openat(duc_dir *dir, const char *name)
{
	struct duc_dirent *e = duc_dir_find_child(dir, name);
	if (!e) return NULL;
	return duc_dir_openent(dir, e);
}

duc_dir *duc_dir_open_parent(duc_dir *dir)
{
	if (dir->devino_parent.dev == 0 && dir->devino_parent.ino == 0) return NULL;
	duc_dir *p = duc_dir_new(dir->duc, &dir->devino_parent);
	if (!p) return NULL;
	char *path = strdup(dir->path);
	char *s = strrchr(path, '/');
	if (s && s != path) *s = 0;
	else if (s == path) s[1] = 0;
	p->path = path;
	return p;
}

duc_dir *duc_dir_open(duc *duc, const char *path)
{
	char *canon = duc_canonicalize_path(path);

	/* find the report with the longest matching prefix */
	size_t n;
	char **list = read_report_list(duc, &n);
	const char *best = NULL;
	size_t best_len = 0;
	for (size_t i = 0; i < n; i++) {
		size_t l = strlen(list[i]);
		if (l == 0) continue;
		if (strncmp(list[i], canon, l) == 0 && l >= best_len) {
			if (l > best_len || best == NULL) {
				best = list[i];
				best_len = l;
			}
		}
	}

	struct duc_index_report *rep = NULL;
	if (best) duc_db_read_report(duc, best, &rep);

	if (!rep) {
		duc_log(duc, DUC_LOG_ERR, "Path %s not found in database", canon);
		duc->err = DUC_E_PATH_NOT_FOUND;
		free_report_list(list, n);
		free(canon);
		return NULL;
	}

	duc_dir *dir = duc_dir_new(duc, &rep->devino);
	if (dir == NULL) {
		duc->err = DUC_E_PATH_NOT_FOUND;
		duc_index_report_free(rep);
		free_report_list(list, n);
		free(canon);
		return NULL;
	}
	dir->path = strdup(rep->path);

	char *rest = strdup(canon + best_len);
	char *saveptr = NULL;
	char *name = strtok_r(rest, "/", &saveptr);
	while (dir && name) {
		struct duc_dirent *e = duc_dir_find_child(dir, name);
		duc_dir *next = NULL;
		if (e) {
			next = duc_dir_openent(dir, e);
		}
		duc_dir_close(dir);
		dir = next;
		name = strtok_r(NULL, "/", &saveptr);
	}
	free(rest);

	if (dir) {
		free(dir->path);
		dir->path = strdup(canon);
	} else {
		duc->err = DUC_E_PATH_NOT_FOUND;
	}

	duc_index_report_free(rep);
	free_report_list(list, n);
	free(canon);
	return dir;
}
