	FILE *f = setmntent("/proc/mounts", "r");
	if (!f) f = setmntent("/etc/mtab", "r");
	if (!f) return;
	struct mntent *m;
	size_t cap = 32;
	req->mount_dirs = malloc(cap * sizeof(char *));
	req->mount_types = malloc(cap * sizeof(char *));
	while ((m = getmntent(f)) != NULL) {
		if (req->mount_count >= cap) {
			cap *= 2;
			req->mount_dirs = realloc(req->mount_dirs, cap * sizeof(char *));
			req->mount_types = realloc(req->mount_types, cap * sizeof(char *));
		}
		req->mount_dirs[req->mount_count] = strdup(m->mnt_dir);
		req->mount_types[req->mount_count] = strdup(m->mnt_type);
		req->mount_count++;
	}
	endmntent(f);
}

static const char *fstype_of_path(duc_index_req *req, const char *path)
{
	load_mounts(req);
	const char *best = NULL;
	size_t best_len = 0;
	for (size_t i = 0; i < req->mount_count; i++) {
		if (strcmp(req->mount_dirs[i], path) == 0) {
			/* exact match: prefer the last one */
			best = req->mount_types[i];
			best_len = (size_t)-1;
		} else if (best_len != (size_t)-1) {
			size_t l = strlen(req->mount_dirs[i]);
			if (strncmp(req->mount_dirs[i], path, l) == 0 &&
			    (l == 1 || path[l] == '/') && l >= best_len) {
				best = req->mount_types[i];
				best_len = l;
			}
		}
	}
	return best ? best : "unknown";
}

static int fstype_in_list(struct fstype *list, const char *name)
{
	for (struct fstype *f = list; f; f = f->next) {
		if (strcmp(f->name, name) == 0) return 1;
	}
	return 0;
}

static int hardlink_seen(duc_index_req *req, uint64_t dev, uint64_t ino)
{
	for (size_t i = 0; i < req->hl_count; i++) {
		if (req->hl[i].dev == dev && req->hl[i].ino == ino) return 1;
	}
	if (req->hl_count >= req->hl_cap) {
		req->hl_cap = req->hl_cap ? req->hl_cap * 2 : 256;
		req->hl = realloc(req->hl, req->hl_cap * sizeof(struct hardlink));
	}
	req->hl[req->hl_count].dev = dev;
	req->hl[req->hl_count].ino = ino;
	req->hl_count++;
	return 0;
}

static int size_bucket(int64_t size)
{
	if (size <= 0) return 0;
	int b = 0;
	uint64_t s = (uint64_t)size;
	while (s > 1) { s >>= 1; b++; }
	return b;
}

static void histogram_add(duc_index_req *req, int64_t size)
{
	struct duc_index_report *rep = req->report;
	int b = size_bucket(size);
	if (b >= rep->buckets) {
		duc_log(req->duc, DUC_LOG_WRN, "File sizes large enough we ran out of histogram buckets %d, please increase the number of buckets and re-run your indexing.", (int)rep->buckets);
		if (rep->buckets < DUC_HIST_RAW_SLOTS) req->raw_hist[rep->buckets]++;
		return;
	}
	rep->histogram[b]++;
	req->raw_hist[b]++;
}

static void topn_add(duc_index_req *req, const char *path, int64_t size)
{
	struct duc_index_report *rep = req->report;
	if (req->topn_cnt <= 0) return;
	if (size <= DUC_TOPN_MIN_SIZE) return;
	struct duc_topn_file *t = rep->topn;
	int n = req->topn_cnt;
	if (size <= t[0].size) return;
	free(t[0].path);
	t[0].path = strdup(path);
	t[0].size = size;
	for (int i = 0; i + 1 < n; i++) {
		if (t[i].size > t[i + 1].size) {
			struct duc_topn_file tmp = t[i];
			t[i] = t[i + 1];
			t[i + 1] = tmp;
		} else {
			break;
		}
	}
}

static void progress_check(duc_index_req *req, int force)
{
	if (!req->progress_fn) return;
	if (!force) {
		if (++req->progress_n <= 100) return;
		req->progress_n = 0;
		struct timeval now;
		gettimeofday(&now, NULL);
		double dt = (now.tv_sec - req->progress_time.tv_sec) +
			    (now.tv_usec - req->progress_time.tv_usec) / 1e6;
		if (req->progress_time.tv_sec != 0 && dt < 0.1) return;
		req->progress_time = now;
	} else {
		gettimeofday(&req->progress_time, NULL);
	}
	req->progress_fn(req->report, req->progress_ptr);
}

/* -------- scanner -------- */

struct scanner {
	duc_index_req *req;
	struct scanner *parent;
	int depth;
	int fd;
	char *path;          /* full path of this directory */
	const char *name;    /* name within parent */
	struct stat st;
	duc_dir dir;         /* devino, devino_parent, mtime */
	struct duc_size size;
	struct duc_dirent *ents;
	size_t ent_count, ent_cap;
	int flags;
};

static void scanner_add_ent(struct scanner *s, const char *name, struct duc_size *size,
			    duc_file_type type, struct duc_devino *devino)
{
	if (s->ent_count >= s->ent_cap) {
		s->ent_cap = s->ent_cap ? s->ent_cap * 2 : 32;
		s->ents = realloc(s->ents, s->ent_cap * sizeof(struct duc_dirent));
	}
	struct duc_dirent *e = &s->ents[s->ent_count++];
	e->name = strdup(name);
	e->size = *size;
	e->type = type;
	if (devino) e->devino = *devino;
	else { e->devino.dev = 0; e->devino.ino = 0; }
}

static void scanner_scan(struct scanner *s)
{
	duc_index_req *req = s->req;
	duc *duc = req->duc;
	struct duc_index_report *rep = req->report;
	int maxdepth = req->maxdepth;

	rep->dir_count++;
	duc_log(duc, DUC_LOG_DBG, ">> %s", s->depth == 0 ? s->path : s->name);

	DIR *d = fdopendir(s->fd);
	if (d == NULL) {
		close(s->fd);
		return;
	}

	struct dirent *de;
	while ((de = readdir(d)) != NULL) {
		const char *name = de->d_name;
		if (name[0] == '.' && (name[1] == 0 || (name[1] == '.' && name[2] == 0))) continue;

		struct stat st;
		if (fstatat(s->fd, name, &st, AT_SYMLINK_NOFOLLOW) < 0) {
			duc_log(duc, DUC_LOG_WRN, "skipping %s/%s: %s", s->path, name, strerror(errno));
			continue;
		}

		/* exclude patterns */
		int excluded = 0;
		for (struct exclude *x = req->exclude_list; x; x = x->next) {
			if (fnmatch(x->pattern, name, 0) == 0) { excluded = 1; break; }
		}
		if (excluded) {
			duc_log(duc, DUC_LOG_WRN, "skipping %s/%s: Excluded by user", s->path, name);
			continue;
		}

		if (req->uid_set && req->uid != 0 && st.st_uid != req->uid) continue;

		duc_file_type type = mode_to_type(st.st_mode);

		if (type == DUC_FILE_TYPE_DIR) {
			size_t pl = strlen(s->path) + 1 + strlen(name) + 1;
			char *cpath = malloc(pl);
			snprintf(cpath, pl, "%s/%s", s->path, name);

			if (st.st_dev != s->st.st_dev) {
				if (s->flags & DUC_INDEX_XDEV) {
					duc_log(duc, DUC_LOG_WRN, "skipping %s: Not crossing file system boundaries", cpath);
					free(cpath);
					continue;
				}
				if (req->fstype_exclude || req->fstype_include) {
					const char *fst = fstype_of_path(req, cpath);
					if (req->fstype_exclude && fstype_in_list(req->fstype_exclude, fst)) {
						duc_log(duc, DUC_LOG_WRN, "skipping %s: File system type '%s' is excluded", cpath, fst);
						free(cpath);
						continue;
					}
					if (req->fstype_include && !fstype_in_list(req->fstype_include, fst)) {
						duc_log(duc, DUC_LOG_WRN, "skipping %s: File system type '%s' is not included", cpath, fst);
						free(cpath);
						continue;
					}
				}
			}

			int fd2 = openat(s->fd, name, O_RDONLY | O_NOCTTY | O_DIRECTORY | O_NOFOLLOW);
			if (fd2 < 0) {
				duc_log(duc, DUC_LOG_WRN, "skipping %s: %s", cpath, strerror(errno));
				free(cpath);
				continue;
			}

			struct scanner *c = calloc(1, sizeof *c);
			c->req = req;
			c->parent = s;
			c->depth = s->depth + 1;
			c->fd = fd2;
			c->path = cpath;
			c->name = name;
			c->st = st;
			c->flags = s->flags;
			c->dir.devino.dev = st.st_dev;
			c->dir.devino.ino = st.st_ino;
			c->dir.devino_parent = s->dir.devino;
			c->dir.mtime = st.st_mtime;

			scanner_scan(c);

			struct duc_size csize = c->size;
			csize.count += 1;
			s->size.apparent += csize.apparent;
			s->size.actual += csize.actual;
			s->size.count += csize.count;

			if (maxdepth == 0 || c->depth < maxdepth) {
				scanner_add_ent(s, name, &csize, DUC_FILE_TYPE_DIR, &c->dir.devino);
			}

			for (size_t i = 0; i < c->ent_count; i++) free(c->ents[i].name);
			free(c->ents);
			free(c->path);
			free(c);

			progress_check(req, 0);
		} else {
			if ((s->flags & DUC_INDEX_CHECK_HARD_LINKS) && st.st_nlink > 1) {
				if (hardlink_seen(req, st.st_dev, st.st_ino)) continue;
			}
			struct duc_size fsize;
			fsize.apparent = st.st_size;
			fsize.actual = (int64_t)st.st_blocks * 512;
			fsize.count = 1;

			duc_log(duc, DUC_LOG_DBG, "  %c %jd %jd %s", duc_file_type_char(type),
				(intmax_t)fsize.apparent, (intmax_t)fsize.actual, name);

			rep->file_count++;
			s->size.apparent += fsize.apparent;
			s->size.actual += fsize.actual;
			s->size.count += fsize.count;

			histogram_add(req, fsize.apparent);
			if (req->topn_cnt > 0) {
				size_t pl = strlen(s->path) + 1 + strlen(name) + 1;
				char *fpath = malloc(pl);
				snprintf(fpath, pl, "%s/%s", s->path, name);
				topn_add(req, fpath, fsize.apparent);
				free(fpath);
			}

			if (maxdepth == 0 || s->depth < maxdepth) {
				const char *ename = (s->flags & DUC_INDEX_HIDE_FILE_NAMES) ? "<FILE>" : name;
				scanner_add_ent(s, ename, &fsize, type, NULL);
			}
		}
	}

	closedir(d);

	/* the directory itself takes up space too */
	s->size.actual += (int64_t)s->st.st_blocks * 512;

	if (!(s->flags & DUC_INDEX_DRY_RUN)) {
		duc_db_write_dir(duc, &s->dir, s->ents, s->ent_count);
	}

	duc_log(duc, DUC_LOG_DBG, "<< %s actual:%jd apparent:%jd", s->depth == 0 ? s->path : s->name,
		(intmax_t)s->size.apparent, (intmax_t)s->size.actual);
}

struct duc_index_report *duc_index(duc_index_req *req, const char *path, int flags)
{
	duc *duc = req->duc;

	if (req->topn_cnt > DUC_TOPN_MAX) {
		duc_log(duc, DUC_LOG_ERR, "Cannot store more than %d topN files", DUC_TOPN_MAX);
		raise(SIGSEGV);
		return NULL;
	}

	struct duc_index_report *rep = calloc(1, sizeof *rep);
	rep->path = duc_canonicalize_path(path);
	rep->topn_min_size = DUC_TOPN_MIN_SIZE;
	rep->topn_cnt = req->topn_cnt > 0 ? req->topn_cnt : DUC_TOPN_DEFAULT;
	rep->topn_max = DUC_TOPN_MAX;
	rep->buckets = req->buckets;
	rep->histogram = calloc(rep->buckets > 0 ? rep->buckets : 1, sizeof(int64_t));
	rep->topn = calloc(rep->topn_cnt, sizeof(struct duc_topn_file));
	for (int64_t i = 0; i < rep->topn_cnt; i++) rep->topn[i].path = strdup("");

	req->report = rep;
	req->raw_hist = calloc(DUC_HIST_RAW_SLOTS, sizeof(int64_t));
	req->progress_n = 0;
	req->progress_time.tv_sec = 0;
	req->progress_time.tv_usec = 0;
	req->hl_count = 0;

	gettimeofday(&rep->time_start, NULL);

	if (!(flags & DUC_INDEX_DRY_RUN)) db_begin(duc->db);

	int fd = open(path, O_RDONLY | O_NOCTTY | O_DIRECTORY | O_NOFOLLOW);
	if (fd < 0) {
		duc_log(duc, DUC_LOG_WRN, "skipping %s: %s", path, strerror(errno));
	} else {
		struct scanner *s = calloc(1, sizeof *s);
		if (fstat(fd, &s->st) < 0) {
			duc_log(duc, DUC_LOG_WRN, "skipping %s: %s", path, strerror(errno));
			close(fd);
			free(s);
		} else {
			s->req = req;
			s->depth = 0;
			s->fd = fd;
			s->path = strdup(path);
			s->name = s->path;
			s->flags = flags;
			s->dir.devino.dev = s->st.st_dev;
			s->dir.devino.ino = s->st.st_ino;
			s->dir.mtime = s->st.st_mtime;
			rep->devino = s->dir.devino;

			scanner_scan(s);

			rep->size = s->size;
			for (size_t i = 0; i < s->ent_count; i++) free(s->ents[i].name);
			free(s->ents);
			free(s->path);
			free(s);
		}
	}

	gettimeofday(&rep->time_stop, NULL);

	if (!(flags & DUC_INDEX_DRY_RUN)) {
		duc_db_write_report(duc, rep, req->raw_hist);
		db_commit(duc->db);
	}

	progress_check(req, 1);

	free(req->raw_hist);
	req->raw_hist = NULL;
	req->report = NULL;
	return rep;
}
EOF
echo ok"}

