static void print_option(struct ducrc_option *o, int with_long)
{
	char name[64];
	if (o->type == DUCRC_TYPE_BOOL) {
		snprintf(name, sizeof name, "%s", o->longopt);
	} else {
		snprintf(name, sizeof name, "%s=VAL", o->longopt);
	}
	if (o->shortopt) {
		printf("  -%c,  --%-20s ", o->shortopt, name);
	} else {
		printf("       --%-20s ", name);
	}
	if (with_long && o->descr_long) {
		printf("%s. ", o->descr_short);
		int col = strlen(o->descr_short);
		char *s = strdup(o->descr_long);
		char *saveptr = NULL;
		char *w = strtok_r(s, " ", &saveptr);
		while (w) {
			int l = strlen(w);
			if (col + l > 48) {
				printf("\n%29s", "");
				col = 0;
			}
			printf("%s ", w);
			col += l + 1;
			w = strtok_r(NULL, " ", &saveptr);
		}
		free(s);
		printf("\n");
	} else {
		printf("%s\n", o->descr_short);
	}
}

void show_help_cmd(struct cmd *cmd)
{
