	printf("\n");
	printf("%s.\n", cmd->descr_short);
	printf("\n");
	printf("Options for the command '%s':\n", cmd->name);
	for (struct ducrc_option *o = cmd->options; o && o->longopt; o++) print_option(o, 1);
	printf("\n");
	printf("Global options:\n");
	for (struct ducrc_option *o = global_options; o->longopt; o++) print_option(o, 1);
	if (cmd->descr_long) {
		printf("\n%s", cmd->descr_long);
	}
}

void show_help_all(void)
{
	printf("usage: duc <cmd> [options] [args]\n");
	printf("\n");
	printf("Available subcommands:\n");
	printf("\n");
	for (struct cmd **c = cmd_list; *c; c++) {
		struct cmd *cmd = *c;
		printf("duc %s [options]%s%s: %s\n", cmd->name, cmd->usage[0] ? " " : "", cmd->usage, cmd->descr_short);
		printf("\n");
		for (struct ducrc_option *o = cmd->options; o && o->longopt; o++) print_option(o, 0);
		printf("\n");
