#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <unistd.h>
#include <limits.h>
#include <ctype.h>
#include <sys/ioctl.h>

#include "duc.h"
#include "cmd.h"

struct cmd *cmd_list[] = {
	&cmd_help,
	&cmd_histogram,
	&cmd_index,
	&cmd_info,
	&cmd_ls,
	&cmd_topn,
	&cmd_xml,
	&cmd_json,
