	&cmd_cgi,
	&cmd_gui,
	&cmd_ui,
	NULL,
};

static int opt_debug = 0;
static int opt_help = 0;
static int opt_quiet = 0;
static int opt_verbose = 0;
static int opt_version = 0;

static struct ducrc_option global_options[] = {
	{ &opt_debug,   "debug",   0,   DUCRC_TYPE_BOOL, "increase verbosity to debug level" },
	{ &opt_help,    "help",    'h', DUCRC_TYPE_BOOL, "show help" },
	{ &opt_quiet,   "quiet",   'q', DUCRC_TYPE_BOOL, "quiet mode, do not print any warning" },
	{ &opt_verbose, "verbose", 'v', DUCRC_TYPE_BOOL, "increase verbosity" },
	{ &opt_version, "version", 0,   DUCRC_TYPE_BOOL, "output version information and exit" },
	{ NULL }
};

int terminal_width(void)
{
	if (isatty(STDOUT_FILENO)) {
		struct winsize w;
		if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &w) == 0) return w.ws_col;
		return 80;
	}
	char *c = getenv("COLUMNS");
	if (c) return atoi(c);
	return 80;
}

void cmd_open_error(duc *duc, const char *db_path, int with_strerror)
{
	(void)db_path;
	(void)with_strerror;
}

static void print_option(struct ducrc_option *o, int with_long)
{
	char name[64];
	if (o->type == DUCRC_TYPE_BOOL) {
		snprintf(name, sizeof name, "%s", o->longopt);
	} else {
		snprintf(name, sizeof name, "%s=VAL", o->longopt);
	}
	if (o->shortopt) {
		printf("  -%c,  --%-20s ", o->shortopt, name);
	} else {
		printf("       --%-20s ", name);
	}
	if (with_long && o->descr_long) {
		printf("%s. ", o->descr_short);
		int col = strlen(o->descr_short);
		char *s = strdup(o->descr_long);
		char *saveptr = NULL;
		char *w = strtok_r(s, " ", &saveptr);
		while (w) {
			int l = strlen(w);
			if (col + l > 48) {
				printf("\n%29s", "");
				col = 0;
			}
			printf("%s ", w);
			col += l + 1;
			w = strtok_r(NULL, " ", &saveptr);
		}
		free(s);
		printf("\n");
	} else {
		printf("%s\n", o->descr_short);
	}
}

void show_help_cmd(struct cmd *cmd)
{
	printf("usage: duc %s [options]%s%s\n", cmd->name, cmd->usage[0] ? " " : "", cmd->usage);
	printf("\n");
	printf("%s.\n", cmd->descr_short);
	printf("\n");
	printf("Options for the command '%s':\n", cmd->name);
	for (struct ducrc_option *o = cmd->options; o && o->longopt; o++) print_option(o, 1);
	printf("\n");
	printf("Global options:\n");
	for (struct ducrc_option *o = global_options; o->longopt; o++) print_option(o, 1);
	if (cmd->descr_long) {
		printf("\n%s", cmd->descr_long);
	}
}

void show_help_all(void)
{
	printf("usage: duc <cmd> [options] [args]\n");
	printf("\n");
	printf("Available subcommands:\n");
	printf("\n");
	for (struct cmd **c = cmd_list; *c; c++) {
		struct cmd *cmd = *c;
		printf("duc %s [options]%s%s: %s\n", cmd->name, cmd->usage[0] ? " " : "", cmd->usage, cmd->descr_short);
		printf("\n");
		for (struct ducrc_option *o = cmd->options; o && o->longopt; o++) print_option(o, 0);
		printf("\n");
	}
}

void show_help_general(void)
{
	printf("usage: duc <cmd> [options] [args]\n");
	printf("\n");
	printf("Available subcommands:\n");
	printf("\n");
	for (struct cmd **c = cmd_list; *c; c++) {
		printf("  %-9s : %s\n", (*c)->name, (*c)->descr_short);
	}
	printf("\n");
	printf("Global options:\n");
	for (struct ducrc_option *o = global_options; o->longopt; o++) print_option(o, 1);
	printf("\n");
	printf("Use 'duc help <subcommand>' or 'duc <subcommand> -h' for a complete list of all\n");
	printf("options and detailed description of the subcommand.\n");
	printf("\n");
	printf("Use 'duc help --all' for a complete list of all options for all subcommands.\n");
}

static struct cmd *find_cmd(const char *name)
{
	for (struct cmd **c = cmd_list; *c; c++) {
		if (strcmp((*c)->name, name) == 0) return *c;
	}
	return NULL;
}

static void apply_option(struct ducrc_option *o, const char *val)
{
	switch (o->type) {
	case DUCRC_TYPE_BOOL:
		*(int *)o->ptr = 1;
		break;
	case DUCRC_TYPE_INT:
		*(int *)o->ptr = atoi(val ? val : "");
		break;
	case DUCRC_TYPE_DOUBLE:
		*(double *)o->ptr = atof(val ? val : "");
		break;
	case DUCRC_TYPE_STRING:
		*(char **)o->ptr = strdup(val ? val : "");
		break;
	case DUCRC_TYPE_FUNC:
		((ducrc_func *)o->ptr)(val ? val : "");
		break;
	}
}

static struct ducrc_option *find_long(struct cmd *cmd, const char *name)
{
	for (struct ducrc_option *o = cmd->options; o && o->longopt; o++) {
		if (strcmp(o->longopt, name) == 0) return o;
	}
	for (struct ducrc_option *o = global_options; o->longopt; o++) {
		if (strcmp(o->longopt, name) == 0) return o;
	}
	return NULL;
}

static void read_ducrc(struct cmd *cmd, const char *path)
{
	FILE *f = fopen(path, "r");
	if (!f) return;
	char line[4096];
	int in_section = 0;
	while (fgets(line, sizeof line, f)) {
		char *p = line;
		while (*p && isspace((unsigned char)*p)) p++;
		char *e = p + strlen(p);
		while (e > p && isspace((unsigned char)e[-1])) *--e = 0;
		if (*p == 0 || *p == '#') continue;
		if (*p == '[') {
			char *q = strchr(p, ']');
			if (q) *q = 0;
			p++;
			in_section = (strcmp(p, "global") == 0 || strcmp(p, cmd->name) == 0);
			continue;
		}
		if (!in_section) continue;
		char *val = p;
		while (*val && !isspace((unsigned char)*val)) val++;
		if (*val) {
			*val++ = 0;
			while (*val && isspace((unsigned char)*val)) val++;
		}
		struct ducrc_option *o = find_long(cmd, p);
		if (!o) {
			fprintf(stderr, "Unknown option '%s'\n", p);
			continue;
		}
		apply_option(o, *val ? val : NULL);
	}
	fclose(f);
}

static void read_config(struct cmd *cmd)
{
	char path[PATH_MAX];
	read_ducrc(cmd, "/etc/ducrc");
	char *home = getenv("HOME");
	if (home) {
		snprintf(path, sizeof path, "%s/.config/duc/ducrc", home);
		read_ducrc(cmd, path);
		snprintf(path, sizeof path, "%s/.ducrc", home);
		read_ducrc(cmd, path);
	}
	read_ducrc(cmd, "./.ducrc");
}

static int parse_options(struct cmd *cmd, int argc, char **argv)
{
	/* build getopt tables */
	int n = 0;
	for (struct ducrc_option *o = cmd->options; o && o->longopt; o++) n++;
	for (struct ducrc_option *o = global_options; o->longopt; o++) n++;

	struct option *longopts = calloc(n + 1, sizeof(struct option));
	struct ducrc_option **map = calloc(n + 1, sizeof(void *));
	char shortopts[256];
	char *sp = shortopts;
	*sp++ = '+';
	int i = 0;
	for (int pass = 0; pass < 2; pass++) {
		struct ducrc_option *list = pass == 0 ? cmd->options : global_options;
		for (struct ducrc_option *o = list; o && o->longopt; o++) {
			longopts[i].name = o->longopt;
			longopts[i].has_arg = (o->type == DUCRC_TYPE_BOOL) ? no_argument : required_argument;
			longopts[i].flag = NULL;
			longopts[i].val = 256 + i;
			map[i] = o;
			if (o->shortopt) {
				*sp++ = o->shortopt;
				if (o->type != DUCRC_TYPE_BOOL) *sp++ = ':';
			}
			i++;
		}
	}
	*sp = 0;
	/* allow option permutation: remove the '+' */
	memmove(shortopts, shortopts + 1, strlen(shortopts));

	optind = 1;
	int c;
	while ((c = getopt_long(argc, argv, shortopts, longopts, NULL)) != -1) {
		struct ducrc_option *o = NULL;
		if (c >= 256 && c < 256 + n) {
			o = map[c - 256];
		} else if (c == '?' || c == ':') {
			fprintf(stderr, "Try 'duc --help' for more information.\n");
			free(longopts);
			free(map);
			return -1;
		} else {
			for (int j = 0; j < n; j++) {
				if (map[j]->shortopt == c) { o = map[j]; break; }
			}
		}
		if (o) apply_option(o, optarg);
	}
	free(longopts);
	free(map);
	return 0;
}

int main(int argc, char **argv)
{
	if (argc < 2) {
		show_help_general();
		return 0;
	}

	if (strcmp(argv[1], "--version") == 0) {
		printf("duc version: %s\n", DUC_VERSION);
		printf("options: %s\n", DUC_OPTIONS);
		return 0;
	}

	struct cmd *cmd = find_cmd(argv[1]);
	if (cmd == NULL) {
		show_help_general();
		return 0;
	}

	duc *duc = duc_new();

	read_config(cmd);

	/* build argv without the subcommand name */
	char **argv2 = calloc(argc, sizeof(char *));
	argv2[0] = argv[0];
	for (int i = 2; i < argc; i++) argv2[i - 1] = argv[i];
	int argc2 = argc - 1;

	if (parse_options(cmd, argc2, argv2) < 0) {
		return 1;
	}

	if (opt_version) {
		printf("duc version: %s\n", DUC_VERSION);
		printf("options: %s\n", DUC_OPTIONS);
		return 0;
	}

	if (opt_help) {
		show_help_cmd(cmd);
		return 0;
	}

	if (opt_debug) duc_set_log_level(duc, DUC_LOG_DBG);
	else if (opt_verbose) duc_set_log_level(duc, DUC_LOG_INF);
	else if (opt_quiet) duc_set_log_level(duc, DUC_LOG_ERR);

	int r = cmd->main(duc, argc2 - optind, argv2 + optind);

	duc_del(duc);
	return r == 0 ? 0 : 1;
}
