static const char *tree_ascii[] = { "|", "`+-", "|-", "`-" };

#define TREE_BAR  0
#define TREE_FIRST 1
#define TREE_MID  2
#define TREE_LAST 3

static void ls_one(duc_dir *dir, int level, int *prefix, const char *path_prefix)
{
	if (level > opt_levels) return;

	const char **tree = opt_ascii ? tree_ascii : tree_utf8;

	size_t n = duc_dir_get_count(dir);
	int64_t max_size = 0;
	size_t max_name_len = 0;

	duc_dir_rewind(dir);
	struct duc_dirent *e;
	while ((e = duc_dir_read(dir, size_type, sort_mode)) != NULL) {
		int64_t s = duc_get_size(&e->size, size_type);
		if (s > max_size) max_size = s;
		size_t l = strlen(e->name);
		if (opt_full_path) l += strlen(path_prefix);
		if (opt_classify) l++;
		if (l > max_name_len) max_name_len = l;
	}

	duc_dir_rewind(dir);
	size_t i = 0;
	while ((e = duc_dir_read(dir, size_type, sort_mode)) != NULL) {
		if (opt_dirs_only && e->type != DUC_FILE_TYPE_DIR) { i++; continue; }

		int64_t size = duc_get_size(&e->size, size_type);

		char siz[64];
		duc_human_size(&e->size, size_type, opt_bytes, siz, sizeof siz);

		const char *color_on = "";
		const char *color_off = "";
		if (opt_color) {
			if (size >= max_size / 2) color_on = "\033[31m";
			else if (size >= max_size / 8) color_on = "\033[33m";
			color_off = "\033[0m";
		}

		if (opt_bytes) {
			printf("%s%12s%s ", color_on, siz, color_off);
		} else {
			printf("%s%6s%s ", color_on, siz, color_off);
		}

		if (opt_recursive && !opt_full_path) {
			for (int j = 0; j < level; j++) {
				if (prefix[j]) printf(" %s  ", tree[TREE_BAR]);
				else printf("    ");
			}
			if (i == 0 && n > 1) printf("%s", tree[TREE_FIRST]);
			else if (i == n - 1) printf(" %s", tree[TREE_LAST]);
			else printf(" %s", tree[TREE_MID]);
			printf(" ");
		}

		char name[8192];
		if (opt_full_path) snprintf(name, sizeof name, "%s%s", path_prefix, e->name);
		else snprintf(name, sizeof name, "%s", e->name);
		if (opt_classify) {
			size_t l = strlen(name);
			if (l + 1 < sizeof name) {
				name[l] = duc_file_type_char(e->type);
				name[l + 1] = 0;
			}
		}
		printf("%s", name);

		if (opt_graph && !opt_full_path) {
			int pad = (int)max_name_len - (int)strlen(name);
			for (int j = 0; j < pad; j++) putchar(' ');
			int w = width - 9 - (int)max_name_len - (opt_bytes ? 12 : 6) - 4 * level;
			if (w < 0) w = 0;
			int l = 0;
			if (max_size > 0) l = (int)((double)w * size / max_size);
			if (l > w) l = w;
			if (l < 0) l = 0;
			printf(" [%s", color_on);
			for (int j = 0; j < l; j++) putchar('+');
			for (int j = l; j < w; j++) putchar(' ');
			printf("%s]", color_off);
		}

		printf("\n");

		if (opt_recursive && e->type == DUC_FILE_TYPE_DIR && level < opt_levels) {
			duc_dir *child = duc_dir_openent(dir, e);
			if (child) {
				prefix[level] = (i < n - 1);
				char *pp = NULL;
				if (opt_full_path) {
					size_t l = strlen(path_prefix) + strlen(e->name) + 2;
					pp = malloc(l);
					snprintf(pp, l, "%s%s/", path_prefix, e->name);
				}
				ls_one(child, level + 1, prefix, pp ? pp : "");
