				duc_dir_close(child);
			}
		}
		i++;
	}
}

static int ls_main(duc *duc, int argc, char **argv)
{
	if (opt_count) size_type = DUC_SIZE_TYPE_COUNT;
	else if (opt_apparent) size_type = DUC_SIZE_TYPE_APPARENT;
