#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "duc.h"
#include "cmd.h"

static int opt_apparent = 0;
static char *opt_database = NULL;
static int opt_exclude_files = 0;
static int opt_min_size = 0;

void xml_print_escaped(const char *s)
{
	for (; *s; s++) {
		switch (*s) {
		case '<': fputs("&lt;", stdout); break;
		case '>': fputs("&gt;", stdout); break;
		case '&': fputs("&amp;", stdout); break;
		case '"': fputs("&quot;", stdout); break;
		default: fputc(*s, stdout); break;
		}
	}
}

static void indent(int n)
{
	for (int i = 0; i < n; i++) putchar(' ');
}

static void dump(duc_dir *dir, int depth, duc_size_type st)
{
	struct duc_dirent *e;
	duc_dir_rewind(dir);
	while ((e = duc_dir_read(dir, st, DUC_SORT_SIZE)) != NULL) {
		int64_t size = duc_get_size(&e->size, st);
		if (size < opt_min_size) continue;
		if (e->type == DUC_FILE_TYPE_DIR) {
			indent(depth);
			printf("<ent type=\"dir\" name=\"");
			xml_print_escaped(e->name);
			printf("\" size_apparent=\"%jd\" size_actual=\"%jd\" count=\"%jd\">\n",
			       (intmax_t)e->size.apparent, (intmax_t)e->size.actual, (intmax_t)e->size.count);
			duc_dir *child = duc_dir_openent(dir, e);
			if (child) {
				dump(child, depth + 1, st);
				duc_dir_close(child);
			}
			indent(depth);
			printf("</ent>\n");
		} else {
			if (opt_exclude_files) continue;
			indent(depth);
			printf("<ent name=\"");
			xml_print_escaped(e->name);
			printf("\" size_apparent=\"%jd\" size_actual=\"%jd\" />\n",
			       (intmax_t)e->size.apparent, (intmax_t)e->size.actual);
		}
	}
}

static int xml_main(duc *duc, int argc, char **argv)
{
	const char *path = argc > 0 ? argv[0] : ".";
	duc_size_type st = opt_apparent ? DUC_SIZE_TYPE_APPARENT : DUC_SIZE_TYPE_ACTUAL;

	if (cmd_db_open(duc, opt_database, DUC_OPEN_RO, 1) != 0) return -1;

	duc_dir *dir = duc_dir_open(duc, path);
	if (dir == NULL) {
		fprintf(stderr, "%s\n", duc_strerror(duc));
		return -1;
	}

	struct duc_size size;
	duc_dir_get_size(dir, &size);

	printf("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
	printf("<duc root=\"");
