static duc_index_req *req;

static void fn_exclude(const char *val)
{
	duc_index_req_add_exclude(req, val);
}

static void fn_fs_exclude(const char *val)
{
	duc_index_req_add_fstype_exclude(req, val);
}

static void fn_fs_include(const char *val)
{
	duc_index_req_add_fstype_include(req, val);
}

static int spinner = 0;

static void progress_cb(struct duc_index_report *rep, void *ptr)
{
	(void)ptr;
	char siz[64], files[64], dirs[64];
	duc_human_size(&rep->size, DUC_SIZE_TYPE_ACTUAL, opt_bytes, siz, sizeof siz);
	duc_human_count(rep->file_count, opt_bytes, files, sizeof files);
	duc_human_count(rep->dir_count, opt_bytes, dirs, sizeof dirs);
	char spin[9];
	for (int i = 0; i < 8; i++) spin[i] = (i == (spinner % 8)) ? '#' : '-';
	spin[8] = 0;
	spinner++;
	fprintf(stderr, "\033[K[%s] Indexed %sb in %s files and %s directories\r", spin, siz, files, dirs);
	fflush(stderr);
}

static int index_main(duc *duc, int argc, char **argv)
{
	int flags = 0;
	if (opt_one_file_system) flags |= DUC_INDEX_XDEV;
	if (opt_hide_file_names) flags |= DUC_INDEX_HIDE_FILE_NAMES;
	if (opt_check_hard_links) flags |= DUC_INDEX_CHECK_HARD_LINKS;
	if (opt_dry_run) flags |= DUC_INDEX_DRY_RUN;
	(void)opt_force;
	(void)opt_uncompressed;
	(void)opt_topn_min;

	if (argc < 1) {
		show_help_cmd(&cmd_index);
		duc_log(duc, DUC_LOG_FTL, "Required index PATH missing.");
		return -1;
	}

	if (opt_username) duc_index_req_set_username(req, opt_username);
	if (opt_uid) duc_index_req_set_uid(req, opt_uid);
	if (opt_max_depth) duc_index_req_set_maxdepth(req, opt_max_depth);
	if (opt_topn) duc_index_req_set_topn(req, opt_topn);
	if (opt_buckets) duc_index_req_set_buckets(req, opt_buckets);
	if (opt_progress) {
		duc_index_req_set_progress_cb(req, progress_cb, NULL);
		duc->log_clear = 1;
	}

	/* check all paths first */
	for (int i = 0; i < argc; i++) {
		struct statvfs vfs;
		if (statvfs(argv[i], &vfs) != 0) {
			duc_log(duc, DUC_LOG_FTL, "Can't run statvfs on %s", argv[i]);
			return -1;
		}
		if (vfs.f_files > 100000000ULL) {
			duc_log(duc, DUC_LOG_INF, "Found big filesystem");
		}
