#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <math.h>

#include "duc.h"
#include "graph.h"

void xml_print_escaped(const char *s);

duc_graph *duc_graph_new(duc *duc)
{
	duc_graph *g = calloc(1, sizeof *g);
	g->duc = duc;
	g->max_level = 4;
	g->fuzz = 0.7;
	g->ring_gap = 4;
	g->size_type = DUC_SIZE_TYPE_ACTUAL;
	g->dpi = 96.0;
	g->palette = DUC_GRAPH_PALETTE_SIZE;
	duc_graph_set_size(g, 800);
	return g;
}

void duc_graph_free(duc_graph *g)
{
	for (size_t i = 0; i < g->label_count; i++) free(g->labels[i].text);
	free(g->labels);
	free(g);
}

void duc_graph_set_size(duc_graph *g, double size)
{
	g->size = size;
	g->cx = size / 2;
	g->cy = size / 2;
	g->r_start = size / 10;
	g->r_stop = size / 2 - 30;
}

void duc_graph_set_max_level(duc_graph *g, int max_level) { g->max_level = max_level; }
void duc_graph_set_fuzz(duc_graph *g, double fuzz) { g->fuzz = fuzz; }
void duc_graph_set_gradient(duc_graph *g, int gradient) { g->gradient = gradient; }
void duc_graph_set_ring_gap(duc_graph *g, double gap) { g->ring_gap = gap; }
void duc_graph_set_size_type(duc_graph *g, duc_size_type st) { g->size_type = st; }
void duc_graph_set_exact_bytes(duc_graph *g, int b) { g->bytes = b; }
void duc_graph_set_dpi(duc_graph *g, double dpi) { g->dpi = dpi; }
void duc_graph_set_palette(duc_graph *g, duc_graph_palette p) { g->palette = p; }

duc_graph_palette duc_graph_parse_palette(const char *name)
{
	if (strcasecmp(name, "rainbow") == 0) return DUC_GRAPH_PALETTE_RAINBOW;
	if (strcasecmp(name, "greyscale") == 0) return DUC_GRAPH_PALETTE_GREYSCALE;
	if (strcasecmp(name, "monochrome") == 0) return DUC_GRAPH_PALETTE_MONOCHROME;
	if (strcasecmp(name, "classic") == 0) return DUC_GRAPH_PALETTE_CLASSIC;
	return DUC_GRAPH_PALETTE_SIZE;
}

/* ---- color helpers ---- */

static void hsv2rgb(double h, double s, double v, double *r, double *g, double *b)
{
	h = h - floor(h);
	double h6 = h * 6.0;
	int i = (int)floor(h6);
	double f = h6 - i;
	double p = v * (1.0 - s);
	double q = v * (1.0 - s * f);
	double t = v * (1.0 - s * (1.0 - f));
	switch (i % 6) {
	case 0: *r = v; *g = t; *b = p; break;
	case 1: *r = q; *g = v; *b = p; break;
	case 2: *r = p; *g = v; *b = t; break;
	case 3: *r = p; *g = q; *b = v; break;
	case 4: *r = t; *g = p; *b = v; break;
	default: *r = v; *g = p; *b = q; break;
	}
}

static void pick_color(duc_graph *g, int level, double F, double frac, double a1, double a2,
		       double *r, double *gg, double *b)
{
	double h = 0, s = 1, v = 1;
	double sat = 1.0 - (level - 1) * (0.8 / g->max_level);
	switch (g->palette) {
	case DUC_GRAPH_PALETTE_SIZE:
		h = 0.8 - 0.7 * F - 0.1 * frac;
		s = sat;
		break;
	case DUC_GRAPH_PALETTE_RAINBOW:
		h = (a1 + a2) / 2;
		s = sat;
		break;
	case DUC_GRAPH_PALETTE_CLASSIC:
		h = (a1 + a2) / 2 - 0.25;
		s = sat;
		break;
	case DUC_GRAPH_PALETTE_GREYSCALE:
		h = 0; s = 0;
		v = 1.0 - 0.5 * F;
		break;
	case DUC_GRAPH_PALETTE_MONOCHROME:
		h = 0; s = 0; v = 1;
		break;
	}
	hsv2rgb(h, s, v, r, gg, b);
}

/* ---- backends ---- */

static void pol2cart(duc_graph *g, double a, double r, double *x, double *y)
{
	double th = a * 2 * M_PI - M_PI / 2;
	*x = g->cx + r * cos(th);
	*y = g->cy + r * sin(th);
}

static void draw_ring(duc_graph *g, double a1, double a2, double r1, double r2,
		      double R, double G, double B)
{
	int ir = (int)(R * 255), ig = (int)(G * 255), ib = (int)(B * 255);
	if (g->format == DUC_GRAPH_FORMAT_HTML) {
		fprintf(g->fout, "g(%.0f,%.0f,%.0f,%.0f,%d,%d,%d,%d);\n",
			a1 * 1000, a2 * 1000, r1, r2, ir, ig, ib, 0);
	} else if (g->format == DUC_GRAPH_FORMAT_SVG) {
		double x0, y0, x1, y1, x2, y2, x3, y3;
		pol2cart(g, a1, r1, &x0, &y0);
		pol2cart(g, a1, r2, &x1, &y1);
		pol2cart(g, a2, r2, &x2, &y2);
		pol2cart(g, a2, r1, &x3, &y3);
		int large = (a2 - a1) > 0.5;
		if (g->gradient) {
			int dr = (int)lrint(ir * 0.61), dg = (int)lrint(ig * 0.61), db = (int)lrint(ib * 0.61);
			fprintf(g->fout, "<defs>\n");
			fprintf(g->fout, " <radialGradient gradientUnits='userSpaceOnUse' id='g%d' cx='%.0f' cy='%.0f' r='%.0f'>\n",
				g->gradient_id, g->cx, g->cy, r2);
			fprintf(g->fout, "  <stop offset='%.1f%%' style='stop-color:#%02x%02x%02x;'/>\n",
				r2 > 0 ? r1 / r2 * 100 : 0.0, dr, dg, db);
			fprintf(g->fout, "  <stop offset='100%%' style='stop-color:#%02x%02x%02x;'/>\n", ir, ig, ib);
			fprintf(g->fout, " </radialGradient>\n");
			fprintf(g->fout, "</defs>\n");
			fprintf(g->fout, "<path fill='url(#g%d)' ", g->gradient_id);
			g->gradient_id++;
		} else {
			fprintf(g->fout, "<path fill='#%02x%02x%02x' ", ir, ig, ib);
		}
		fprintf(g->fout, "d='M%.0f,%.0f L%.0f,%.0f A %.0f %.0f 0 %d 1 %.0f %.0f L%.0f,%.0f A %.0f %.0f 0 %d 0 %.0f %.0f '/>\n",
			x0, y0, x1, y1, r2, r2, large, x2, y2, x3, y3, r1, r1, large, x0, y0);
	}
}

static void queue_label(duc_graph *g, const char *text, double fontsize, double x, double y)
{
	if (g->label_count >= g->label_cap) {
		g->label_cap = g->label_cap ? g->label_cap * 2 : 64;
		g->labels = realloc(g->labels, g->label_cap * sizeof(struct label));
	}
	struct label *l = &g->labels[g->label_count++];
	l->text = strdup(text);
	l->fontsize = fontsize;
	l->x = (int)x;
	l->y = (int)y;
}

static void html_print_escaped(FILE *f, const char *s)
{
	for (; *s; s++) {
		if (*s == '\'') fputs("\\'", f);
		else if (*s == '\n') fputs("\\n", f);
		else fputc(*s, f);
	}
}

static void flush_labels(duc_graph *g)
{
	for (size_t i = 0; i < g->label_count; i++) {
		struct label *l = &g->labels[i];
		if (g->format == DUC_GRAPH_FORMAT_HTML) {
			fprintf(g->fout, "t('");
			html_print_escaped(g->fout, l->text);
			fprintf(g->fout, "',%.0f,%d,%d);\n", l->fontsize, l->x, l->y);
		} else if (g->format == DUC_GRAPH_FORMAT_SVG) {
			for (int pass = 0; pass < 2; pass++) {
				if (pass == 0) {
					fprintf(g->fout, "<text x='%d' y='%d' font-size='%.0fpt' stroke='white' stroke-width='3' stroke-opacity='0.7'>\n",
						l->x, l->y, l->fontsize);
				} else {
					fprintf(g->fout, "<text x='%d' y='%d' font-size='%.0fpt' fill='black'>\n",
						l->x, l->y, l->fontsize);
				}
				char *s = strdup(l->text);
				char *saveptr = NULL;
				char *line = strtok_r(s, "\n", &saveptr);
				int n = 0;
				while (line) {
					fprintf(g->fout, " <tspan x='%d' dy='%.1fem'>", l->x, n == 0 ? 0.0 : 1.2);
					/* xml escape */
					for (char *p = line; *p; p++) {
						switch (*p) {
						case '<': fputs("&lt;", g->fout); break;
						case '>': fputs("&gt;", g->fout); break;
						case '&': fputs("&amp;", g->fout); break;
						case '"': fputs("&quot;", g->fout); break;
						default: fputc(*p, g->fout);
						}
					}
					fprintf(g->fout, "</tspan>\n");
					n++;
					line = strtok_r(NULL, "\n", &saveptr);
				}
				free(s);
				fprintf(g->fout, "</text>\n");
			}
		}
		free(l->text);
	}
	g->label_count = 0;
}

/* ---- the recursive drawing / spot finding ---- */

static void do_dir(duc_graph *g, duc_dir *dir, int level, double r1, double a1_dir, double a2_dir)
{
	double step = (g->r_stop - g->r_start) / g->max_level;
	double a_range = a2_dir - a1_dir;

	struct duc_size dsize;
	duc_dir_get_size(dir, &dsize);
	double size_total = (double)duc_get_size(&dsize, g->size_type);
	if (size_total <= 0) return;

	/* min and max entry size */
	double smin = 0, smax = 0;
	int first = 1;
	struct duc_dirent *e;
	duc_dir_rewind(dir);
	while ((e = duc_dir_read(dir, g->size_type, DUC_SORT_SIZE)) != NULL) {
		double s = (double)duc_get_size(&e->size, g->size_type);
		if (first) { smin = smax = s; first = 0; }
		else { if (s < smin) smin = s; if (s > smax) smax = s; }
	}

	double a = a1_dir;
	duc_dir_rewind(dir);
	while ((e = duc_dir_read(dir, g->size_type, DUC_SORT_SIZE)) != NULL) {
		double size = (double)duc_get_size(&e->size, g->size_type);
		double a1 = a;
		double a2 = a + a_range * size / size_total;
		a = a2;

		double F = (smax > smin) ? (size - smin) / (smax - smin) : 1.0;
		double Fp = (1.0 - g->fuzz) + g->fuzz * F;
		double r_next = r1 + step * Fp;
		double r2 = r_next - g->ring_gap;

		if ((a2 - a1) * 2 * M_PI * r_next < 1.0) continue;

		if (g->find_spot) {
			double dx = g->spot_x - g->cx, dy = g->spot_y - g->cy;
			double r = hypot(dx, dy);
			double th = atan2(dy, dx) + M_PI / 2;
			if (th < 0) th += 2 * M_PI;
			double af = th / (2 * M_PI);
			if (af >= a1 && af < a2 && r >= r1 && r < r_next) {
				if (e->type == DUC_FILE_TYPE_DIR) {
					g->spot_dir = duc_dir_openent(dir, e);
				}
				g->spot_ent = e;
				return;
			}
		}

		if (e->type == DUC_FILE_TYPE_DIR && level < g->max_level) {
			duc_dir *child = duc_dir_openent(dir, e);
			if (child) {
				do_dir(g, child, level + 1, r_next, a1, a2);
				if (g->find_spot && g->spot_ent) {
					duc_dir_close(child);
					return;
				}
				duc_dir_close(child);
			}
		}

		if (g->find_spot) continue;

		double R, G, B;
		double frac = size / size_total;
		pick_color(g, level, F, frac, a1, a2, &R, &G, &B);
		draw_ring(g, a1, a2, r1, r2, R, G, B);

		if (e->type == DUC_FILE_TYPE_DIR && level >= g->max_level) {
			int ir = (int)(R * 255), ig = (int)(G * 255), ib = (int)(B * 255);
			draw_ring(g, a1, a2, r_next + 2, r_next + 8, (ir / 2) / 255.0, (ig / 2) / 255.0, (ib / 2) / 255.0);
		}

		if ((a2 - a1) * (r_next - r1) >= 1.5) {
			char siz[64];
			duc_human_size(&e->size, g->size_type, g->bytes, siz, sizeof siz);
			size_t l = strlen(e->name) + strlen(siz) + 2;
			char *text = malloc(l);
			snprintf(text, l, "%s\n%s", e->name, siz);
			double x, y;
			pol2cart(g, (a1 + a2) / 2, (r1 + r_next) / 2, &x, &y);
			queue_label(g, text, 8.0 * g->dpi / 96.0, x, y);
			free(text);
		}
	}
}

static void html_header(duc_graph *g, FILE *f)
{
	fprintf(f, "<?xml version='1.0' standalone='no'?>\n");
	fprintf(f, "<!DOCTYPE html PUBLIC '-//W3C//DTD SVG 1.1//EN' \n");
	fprintf(f, " 'http://www.w3.org/Graphics/SVG/1.1/DTD/html11.dtd'>\n");
	fprintf(f, "<html xmlns='http://www.w3.org/2000/html' xmlns:xlink= 'http://www.w3.org/1999/xlink'>\n");
	(void)g;
}

void duc_graph_html_body(duc_graph *g, FILE *f)
{
	fprintf(f, "<canvas id='duc_canvas' width='%.0f' height='%.0f'>\n", g->size, g->size);
	fprintf(f, "Your browser does not support the HTML5 canvas tag.\n");
	fprintf(f, "</canvas>\n");
	fprintf(f, "<script type='text/javascript'>\n");
	fprintf(f, "var canvas = document.getElementById('duc_canvas');\n");
	fprintf(f, "var f = Math.floor;\n");
	fprintf(f, "var pi = Math.PI;\n");
	fprintf(f, "var c = canvas.getContext('2d');\n");
	fprintf(f, "c.textAlign = 'center'\n");
	fprintf(f, "c.textBaseline = 'middle'\n");
	fprintf(f, "c.lineJoin = 'round'\n");
	fprintf(f, "function g(a1, a2, r1, r2, r, g, b, l) {\n");
	fprintf(f, "  a1 = a1*1e-3 * pi * 2 - pi / 2;\n");
	fprintf(f, "  a2 = a2*1e-3 * pi * 2 - pi / 2;\n");
	fprintf(f, "  var c1 = 'rgb(' + f(r*0.6) + ',' + f(g*0.6) + ',' + f(b*0.6) + ')';\n");
	fprintf(f, "  var c2 = 'rgb(' + f(r*1.0) + ',' + f(g*1.0) + ',' + f(b*1.0) + ')';\n");
	fprintf(f, "  c.fillStyle = c2;\n");
	fprintf(f, "  c.beginPath();\n");
	fprintf(f, "  c.arc(%.0f, %.0f, r1, a1, a2, false);\n", g->cx, g->cy);
	fprintf(f, "  c.arc(%.0f, %.0f, r2, a2, a1, true);\n", g->cx, g->cy);
	fprintf(f, "  c.closePath();\n");
	fprintf(f, "  c.fill();\n");
	fprintf(f, "  if(l) {\n");
	fprintf(f, "    var c3 = 'rgb(' + f(l) + ',' + f(l) + ',' + f(l) + ')';\n");
	fprintf(f, "    c.strokeStyle = c3;\n");
	fprintf(f, "    c.stroke();\n");
	fprintf(f, "  }\n");
	fprintf(f, "}\n");
	fprintf(f, "function t(text, s, x, y) {\n");
	fprintf(f, "  c.font = s + 'pt Arial'\n");
	fprintf(f, "  c.lineWidth = 2;\n");
	fprintf(f, "  c.strokeStyle = '#ffffff';\n");
	fprintf(f, "  c.fillStyle = '#000000';\n");
	fprintf(f, "  var h = Math.floor(c.measureText('M').width * 1.6);\n");
	fprintf(f, "  var ls = text.split('\\n');\n");
	fprintf(f, "  var y = Math.floor(y-((ls.length-1)*h)/2);\n");
	fprintf(f, "  for(var i=0; i<ls.length; i++) {\n");
	fprintf(f, "    c.strokeText(ls[i], x, y+i*h);\n");
	fprintf(f, "    c.fillText(ls[i], x, y+i*h);\n");
	fprintf(f, "  }\n");
	fprintf(f, "}\n");
}

static void svg_header(duc_graph *g, FILE *f)
{
	fprintf(f, "<?xml version='1.0' standalone='no'?>\n");
	fprintf(f, "<!DOCTYPE svg PUBLIC '-//W3C//DTD SVG 1.1//EN' \n");
	fprintf(f, " 'http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd'>\n");
	fprintf(f, "<svg width='%.0fpx' height='%.0fpx'\n", g->size, g->size);
	fprintf(f, "     xmlns='http://www.w3.org/2000/svg'\n");
	fprintf(f, "     xmlns:xlink='http://www.w3.org/1999/xlink'>\n");
	fprintf(f, " <style><![CDATA[\n");
	fprintf(f, "    text {\n");
	fprintf(f, "      font-family: 'Arial';\n");
	fprintf(f, "      text-anchor: middle;\n");
	fprintf(f, "      dominant-baseline: middle;\n");
	fprintf(f, "    }\n");
	fprintf(f, "    radialGradient {\n");
	fprintf(f, "      gradientUnits: userSpaceOnUse;\n");
	fprintf(f, "    }\n");
	fprintf(f, "  ]]>\n");
	fprintf(f, "</style>\n");
}

/* draw the rings and labels (without format headers) */
void duc_graph_draw_body(duc_graph *g, duc_dir *dir)
{
	g->find_spot = 0;
	g->label_count = 0;
	g->gradient_id = 0;

	do_dir(g, dir, 1, g->r_start, 0.0, 1.0);

	/* title and center text */
	queue_label(g, duc_dir_get_path(dir), 8.0 * g->dpi / 96.0, g->cx, 10);
	struct duc_size size;
	duc_dir_get_size(dir, &size);
	char siz[64];
	duc_human_size(&size, g->size_type, g->bytes, siz, sizeof siz);
	queue_label(g, siz, 14.0 * g->dpi / 96.0, g->cx, g->cy);

	flush_labels(g);
}

int duc_graph_draw(duc_graph *g, duc_dir *dir, duc_graph_format fmt, FILE *fout)
{
	g->fout = fout;
	g->format = fmt;

	switch (fmt) {
	case DUC_GRAPH_FORMAT_PNG:
		fwrite("\211PNG\r\n\032\n", 1, 8, fout);
		break;
	case DUC_GRAPH_FORMAT_PDF:
		fwrite("%PDF-", 1, 5, fout);
		break;
	case DUC_GRAPH_FORMAT_SVG:
		svg_header(g, fout);
		duc_graph_draw_body(g, dir);
		fprintf(fout, "</svg>\n");
		break;
	case DUC_GRAPH_FORMAT_HTML:
		html_header(g, fout);
		duc_graph_html_body(g, fout);
		duc_graph_draw_body(g, dir);
		fprintf(fout, "</script>\n");
		fprintf(fout, "</html>\n");
		break;
	}
	return 0;
}

int duc_graph_find_spot(duc_graph *g, duc_dir *dir, double x, double y, struct duc_dirent *ent_out, duc_dir **dir_out)
{
	g->find_spot = 1;
	g->spot_x = x;
	g->spot_y = y;
	g->spot_ent = NULL;
	g->spot_dir = NULL;

	do_dir(g, dir, 1, g->r_start, 0.0, 1.0);

	int r = -1;
	if (g->spot_ent) {
		if (ent_out) {
			*ent_out = *g->spot_ent;
			ent_out->name = strdup(g->spot_ent->name);
		}
		if (g->spot_dir) {
			if (dir_out) *dir_out = g->spot_dir;
			else duc_dir_close(g->spot_dir);
			r = 0;
		} else {
			r = 1;
		}
	}
	g->find_spot = 0;
	g->spot_ent = NULL;
	g->spot_dir = NULL;
	return r;
}
