#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <time.h>

#include "duc.h"
#include "cmd.h"
#include "graph.h"

void xml_print_escaped(const char *s);
void duc_graph_html_body(duc_graph *g, FILE *f);
void duc_graph_draw_body(duc_graph *g, duc_dir *dir);

static int opt_apparent = 0;
static int opt_bytes = 0;
static int opt_count = 0;
static char *opt_css_url = NULL;
static char *opt_database = NULL;
static double opt_dpi = 96.0;
static char *opt_footer = NULL;
static double opt_fuzz = 0.7;
static int opt_gradient = 0;
static char *opt_header = NULL;
static int opt_levels = 4;
static int opt_list = 0;
static char *opt_palette = NULL;
static double opt_ring_gap = 4;
static int opt_size = 800;
static int opt_tooltip = 0;

struct param {
	char *key;
	char *val;
	struct param *next;
};

static struct param *params = NULL;

static void url_decode(char *s)
{
	char *d = s;
	while (*s) {
		if (*s == '%' && isxdigit((unsigned char)s[1]) && isxdigit((unsigned char)s[2])) {
			char hex[3] = { s[1], s[2], 0 };
			*d++ = (char)strtol(hex, NULL, 16);
			s += 3;
		} else if (*s == '+') {
			*d++ = ' ';
			s++;
		} else {
			*d++ = *s++;
		}
	}
	*d = 0;
}

static void parse_query(void)
{
	char *qs = getenv("QUERY_STRING");
	if (!qs) return;
	char *s = strdup(qs);
	char *saveptr = NULL;
	char *tok = strtok_r(s, "&", &saveptr);
	while (tok) {
		char *eq = strchr(tok, '=');
		struct param *p = calloc(1, sizeof *p);
		if (eq) {
			*eq = 0;
			p->key = strdup(tok);
			p->val = strdup(eq + 1);
		} else {
			p->key = strdup(tok);
			p->val = strdup("");
		}
		url_decode(p->key);
		url_decode(p->val);
		p->next = params;
		params = p;
		tok = strtok_r(NULL, "&", &saveptr);
	}
	free(s);
}

static const char *get_param(const char *key)
{
	for (struct param *p = params; p; p = p->next) {
		if (strcmp(p->key, key) == 0) return p->val;
	}
	return NULL;
}

static void print_css(void)
{
	if (opt_css_url) {
		printf("<link rel=\"stylesheet\" type=\"text/css\" href=\"%s\">\n", opt_css_url);
		return;
	}
	printf("<style>\n");
	printf("body { font-family: \"arial\", \"sans-serif\"; font-size: 11px; }\n");
	printf("table, thead, tbody, tr, td, th { font-size: inherit; font-family: inherit; }\n");
	printf("#main { display:table-cell; }\n");
	printf("#index { border-bottom: solid 1px #777777; }\n");
	printf("#index table td { padding-left: 5px; }\n");
	printf("#graph { float: left; }\n");
	printf("#list { float: left; }\n");
	printf("#list table { margin-left: auto; margin-right: auto; }\n");
	printf("#list table td { padding-left: 5px; }\n");
	printf("#list table td.name, th.name { text-align: left; }\n");
	printf("#list table td.size, th.size { text-align: right; }\n");
	printf("#tooltip { display: none; position: absolute; background-color: white;\n");
	printf("           border: solid 1px black; padding: 3px; white-space: nowrap; }\n");
	printf("</style>\n");
}

static void print_script(const char *path)
{
	printf("<script>\n");
	printf("  window.onload = function() {\n");
	printf("    var img = document.getElementById('duc_canvas');\n");
	printf("    var tt = document.getElementById('tooltip');\n");
	printf("    var timer;\n");
	printf("    img.onmousedown = function(e) {\n");
	printf("      if(e.button == 0) {\n");
	printf("        var rect = img.getBoundingClientRect(img);\n");
	printf("        var x = e.clientX - rect.left;\n");
	printf("        var y = e.clientY - rect.top;\n");
	printf("        window.location = '?x=' + x + '&y=' + y + '&path=%s';\n", path);
	printf("      }\n");
	printf("    }\n");
	if (opt_tooltip) {
		printf("    img.onmouseout = function() { tt.style.display = \"none\"; };\n");
		printf("    img.onmousemove = function(e) {\n");
		printf("      if(timer) clearTimeout(timer);\n");
		printf("      timer = setTimeout(function() {\n");
		printf("        var rect = img.getBoundingClientRect(img);\n");
		printf("        var x = e.clientX - rect.left;\n");
		printf("        var y = e.clientY - rect.top;\n");
		printf("        var req = new XMLHttpRequest();\n");
		printf("        req.onreadystatechange = function() {\n");
		printf("          if(req.readyState == 4 && req.status == 200) {\n");
		printf("            tt.style.display = tt.innerHTML.length > 0 ? \"block\" : \"none\";\n");
		printf("            tt.style.left = (e.pageX - tt.offsetWidth / 2) + \"px\";\n");
		printf("            tt.style.top = (e.pageY - tt.offsetHeight - 5) + \"px\";\n");
		printf("            tt.innerHTML = req.responseText;\n");
		printf("          }\n");
		printf("        };\n");
		printf("        req.open(\"GET\", \"?cmd=tooltip&path=%s&x=\"+x+\"&y=\"+y , true);\n", path);
		printf("        req.send()\n");
		printf("      }, 100);\n");
		printf("    };\n");
	}
	printf("  };\n");
	printf("</script>\n");
}

static void include_file(const char *path)
{
	if (!path) return;
	FILE *f = fopen(path, "r");
	if (!f) return;
	printf("<!-- start include -->\n");
	char buf[4096];
	size_t n;
	while ((n = fread(buf, 1, sizeof buf, f)) > 0) fwrite(buf, 1, n, stdout);
	fclose(f);
	printf("<!-- end include -->\n");
}

static void print_error(const char *msg)
{
	printf("Content-Type: text/plain\n\n%s\n", msg);
}

static duc_graph *make_graph(duc *duc)
{
	duc_graph *g = duc_graph_new(duc);
	duc_graph_set_size(g, opt_size);
	duc_graph_set_max_level(g, opt_levels);
	duc_graph_set_fuzz(g, opt_fuzz);
	duc_graph_set_gradient(g, opt_gradient);
	duc_graph_set_ring_gap(g, opt_ring_gap);
	duc_graph_set_dpi(g, opt_dpi);
	duc_graph_set_exact_bytes(g, opt_bytes);
	if (opt_palette) duc_graph_set_palette(g, duc_graph_parse_palette(opt_palette));
	if (opt_count) duc_graph_set_size_type(g, DUC_SIZE_TYPE_COUNT);
	else if (opt_apparent) duc_graph_set_size_type(g, DUC_SIZE_TYPE_APPARENT);
	return g;
}

static duc_size_type size_type(void)
{
	if (opt_count) return DUC_SIZE_TYPE_COUNT;
	if (opt_apparent) return DUC_SIZE_TYPE_APPARENT;
	return DUC_SIZE_TYPE_ACTUAL;
}

static void do_index(duc *duc, const char *script_name, const char *path)
{
	duc_dir *dir = NULL;
	if (path) {
		dir = duc_dir_open(duc, path);
		if (dir == NULL) {
			print_error(duc_strerror(duc));
			return;
		}
	}

	const char *xs = get_param("x");
	const char *ys = get_param("y");
	if (dir && xs && ys) {
		double x = atof(xs), y = atof(ys);
		duc_graph *g = make_graph(duc);
		char *newpath = NULL;
		double dx = x - g->cx, dy = y - g->cy;
		if (dx * dx + dy * dy < g->r_start * g->r_start) {
			duc_dir *parent = duc_dir_open_parent(dir);
			if (parent) {
				newpath = strdup(duc_dir_get_path(parent));
				duc_dir_close(parent);
			}
		} else {
			duc_dir *hit = NULL;
			int r = duc_graph_find_spot(g, dir, x, y, NULL, &hit);
			if (r == 0 && hit) {
				newpath = strdup(duc_dir_get_path(hit));
				duc_dir_close(hit);
			}
		}
		duc_graph_free(g);
		if (newpath) {
			printf("Status: 302 Found\n");
			printf("Location: ?path=%s\n", newpath);
			printf("URI: ?path=%s\n", newpath);
			printf("Connection: close\n");
			printf("Content-type: text/html\n");
			printf("\n\n");
			free(newpath);
			duc_dir_close(dir);
			return;
		}
	}

	printf("Content-Type: text/html\n\n");
	printf("<!DOCTYPE html>\n");
	printf("<head>\n");
	printf("  <meta charset=\"utf-8\" />\n");
	print_css();
	if (dir) print_script(path);
	printf("</head>\n");
	printf("<body>\n");
	include_file(opt_header);
	printf("<div id=main>\n");
	printf("<div id=index> <table>\n");
	printf("  <tr>\n");
	printf("   <th>Path</th>\n");
	printf("   <th>Size</th>\n");
	printf("   <th>Files</th>\n");
	printf("   <th>Directories</th>\n");
	printf("   <th>Date</th>\n");
	printf("   <th>Time</th>\n");
	printf("  </tr>\n");

	size_t i = 0;
	struct duc_index_report *rep;
	while ((rep = duc_get_report(duc, i)) != NULL) {
		char ts_date[32], ts_time[32];
		struct tm *tm = localtime(&rep->time_start.tv_sec);
		strftime(ts_date, sizeof ts_date, "%Y-%m-%d", tm);
		strftime(ts_time, sizeof ts_time, "%H:%M:%S", tm);
		char siz[64];
		duc_human_size(&rep->size, size_type(), 0, siz, sizeof siz);
		printf("  <tr>\n");
		printf("   <td><a href=\"%s?cmd=index&path=%s\">%s</a></td>\n", script_name, rep->path, rep->path);
		printf("   <td>%s</td>\n", siz);
		printf("   <td>%jd</td>\n", (intmax_t)rep->file_count);
		printf("   <td>%jd</td>\n", (intmax_t)rep->dir_count);
		printf("   <td>%s</td>\n", ts_date);
		printf("   <td>%s</td>\n", ts_time);
		printf("  </tr>\n");
		duc_index_report_free(rep);
		i++;
	}
	printf(" </table>\n");

	if (dir) {
		duc_graph *g = make_graph(duc);
		printf("<div id=graph>\n");
		g->fout = stdout;
		g->format = DUC_GRAPH_FORMAT_HTML;
		duc_graph_html_body(g, stdout);
		duc_graph_draw_body(g, dir);
		printf("</script>\n");
		printf("</div>\n");

		if (opt_list) {
			printf("<div id=list>\n");
			printf(" <table>\n");
			printf("  <tr>\n");
			printf("   <th class=name>Filename</th>\n");
			printf("   <th class=size>Size</th>\n");
			printf("  </tr>\n");
			struct duc_dirent *e;
			duc_dir_rewind(dir);
			while ((e = duc_dir_read(dir, size_type(), DUC_SORT_SIZE)) != NULL) {
				char siz[64];
				duc_human_size(&e->size, size_type(), opt_bytes, siz, sizeof siz);
				if (e->type == DUC_FILE_TYPE_DIR) {
					printf("  <tr><td class=name><a href=\"%s?cmd=index&path=%s/%s\">", script_name, duc_dir_get_path(dir), e->name);
					xml_print_escaped(e->name);
					printf("</a>\n");
				} else {
