	if (opt_count) return DUC_SIZE_TYPE_COUNT;
	if (opt_apparent) return DUC_SIZE_TYPE_APPARENT;
	return DUC_SIZE_TYPE_ACTUAL;
}

static void attr_on(int pair, int fallback)
{
	if (use_color) attron(COLOR_PAIR(pair));
	else if (fallback) attron(fallback);
}

static void attr_off(int pair, int fallback)
{
	if (use_color) attroff(COLOR_PAIR(pair));
	else if (fallback) attroff(fallback);
}

static void draw(duc_dir *dir, int cur, int top)
{
	int rows, cols;
	getmaxyx(stdscr, rows, cols);
	duc_size_type st = cur_size_type();
	duc_sort sort = opt_name_sort ? DUC_SORT_NAME : DUC_SORT_SIZE;

	erase();

	/* title */
	attr_on(PAIR_TITLE, A_REVERSE);
	mvhline(0, 0, ' ', cols);
	if (topn_mode) {
		mvprintw(0, 0, "  %jd largest files", (intmax_t)topn_cnt);
	} else {
		mvprintw(0, 0, "  %s", duc_dir_get_path(dir));
	}
	attr_off(PAIR_TITLE, A_REVERSE);

	/* find max size */
	int64_t max_size = 0;
	struct duc_dirent *e;
	duc_dir_rewind(dir);
	while ((e = duc_dir_read(dir, st, sort)) != NULL) {
		int64_t s = duc_get_size(&e->size, st);
		if (s > max_size) max_size = s;
	}

	int bar_w = cols / 2;
	int name_max = cols - bar_w - 12;
	if (name_max < 0) name_max = 0;
	int bar_x = cols - bar_w - 3;

	int y = 1;
	int idx = 0;
	duc_dir_rewind(dir);
	while ((e = duc_dir_read(dir, st, sort)) != NULL) {
		if (idx < top) { idx++; continue; }
		if (y >= rows - 1) break;

		int sel = (idx == cur);
		int64_t size = duc_get_size(&e->size, st);
		char siz[64];
		duc_human_size(&e->size, st, opt_bytes, siz, sizeof siz);

		char name[8192];
		snprintf(name, sizeof name, "%s%c", e->name, duc_file_type_char(e->type));
		size_t nl = strlen(name);
		int clen = nl > 0 ? (int)nl - 1 : 0; /* name without classify char */
		if ((int)nl > name_max) { name[name_max] = 0; nl = name_max; if (clen > name_max) clen = name_max; }

		move(y, 0);
		if (sel) {
			attr_on(PAIR_SEL, A_REVERSE);
			mvhline(y, 0, ' ', cols);
			if (opt_bytes) mvprintw(y, 0, " %12s ", siz);
			else mvprintw(y, 0, " %6s ", siz);
			printw("%s", name);
		} else {
			attr_on(PAIR_NORMAL, 0);
			mvhline(y, 0, ' ', cols);
			if (opt_bytes) mvprintw(y, 0, " %12s ", siz);
			else mvprintw(y, 0, " %6s ", siz);
			attr_off(PAIR_NORMAL, 0);
			attr_on(PAIR_NAME, A_BOLD);
			printw("%.*s", clen, name);
			attr_off(PAIR_NAME, A_BOLD);
			if ((int)nl > clen) {
				attr_on(PAIR_CLASS, 0);
				printw("%s", name + clen);
				attr_off(PAIR_CLASS, 0);
			}
			attr_on(PAIR_NORMAL, 0);
		}

		if (bar_x > 0 && bar_x < cols) {
			if (!sel) { attr_off(PAIR_NORMAL, 0); attr_on(PAIR_BAR, 0); }
			move(y, bar_x);
			int l = 0;
			if (max_size > 0) l = (int)((double)bar_w * size / max_size);
			if (l > bar_w) l = bar_w;
			char bar[4096];
			int p = 0;
			bar[p++] = ' ';
			bar[p++] = '[';
			for (int i = 0; i < bar_w && p < (int)sizeof bar - 2; i++) bar[p++] = (i < l) ? '=' : ' ';
			bar[p++] = ']';
			bar[p] = 0;
			printw("%s", bar);
			if (!sel) attr_off(PAIR_BAR, 0);
		}
		if (sel) attr_off(PAIR_SEL, A_REVERSE);
		else attr_off(PAIR_NORMAL, 0);

		y++;
		idx++;
	}

	for (; y < rows - 1; y++) {
		attron(A_DIM);
		if (use_color) attron(COLOR_PAIR(PAIR_NORMAL));
		mvprintw(y, 0, "~");
		if (use_color) attroff(COLOR_PAIR(PAIR_NORMAL));
		attroff(A_DIM);
	}

	/* footer */
	struct duc_size size;
	duc_dir_get_size(dir, &size);
	char siz[64];
	duc_human_size(&size, st, opt_bytes, siz, sizeof siz);
	attr_on(PAIR_TITLE, A_REVERSE);
	mvhline(rows - 1, 0, ' ', cols);
	if (st == DUC_SIZE_TYPE_COUNT) {
		mvprintw(rows - 1, 0, " Total %s files, %jd files and %jd directories here",
			 siz, (intmax_t)dir->file_count, (intmax_t)dir->dir_count);
	} else {
		mvprintw(rows - 1, 0, " Total %sB in %jd files and %jd directories (%s size)",
			 siz, (intmax_t)dir->file_count, (intmax_t)dir->dir_count,
			 st == DUC_SIZE_TYPE_APPARENT ? "apparent" : "actual");
	}
	attr_off(PAIR_TITLE, A_REVERSE);

	refresh();
}

static void show_help(void)
{
	endwin();
	FILE *f = popen("less", "w");
	if (f) {
		fputs(cmd_ui.descr_long, f);
		pclose(f);
	}
	refresh();
}

static struct duc_dirent *ent_at(duc_dir *dir, int idx)
{
	duc_size_type st = cur_size_type();
	duc_sort sort = opt_name_sort ? DUC_SORT_NAME : DUC_SORT_SIZE;
	duc_dir_rewind(dir);
	struct duc_dirent *e;
	int i = 0;
	while ((e = duc_dir_read(dir, st, sort)) != NULL) {
		if (i == idx) return e;
		i++;
	}
	return NULL;
}

static int find_ent_by_devino(duc_dir *dir, const struct duc_devino *devino)
{
	duc_size_type st = cur_size_type();
	duc_sort sort = opt_name_sort ? DUC_SORT_NAME : DUC_SORT_SIZE;
	duc_dir_rewind(dir);
	struct duc_dirent *e;
	int i = 0;
	while ((e = duc_dir_read(dir, st, sort)) != NULL) {
		if (e->type == DUC_FILE_TYPE_DIR && e->devino.dev == devino->dev && e->devino.ino == devino->ino) return i;
		i++;
	}
	return 0;
}

static int ui_main(duc *duc, int argc, char **argv)
{
	const char *path = argc > 0 ? argv[0] : ".";

	if (cmd_db_open(duc, opt_database, DUC_OPEN_RO, 0) != 0) return -1;

	duc_dir *dir = duc_dir_open(duc, path);
	if (dir == NULL) {
		duc_log(duc, DUC_LOG_FTL, "The requested path '%s' was not found in the database,", path);
		duc_log(duc, DUC_LOG_FTL, "Please run 'duc info' for a list of available directories.");
		return -1;
	}

	{
		struct duc_index_report *rep = duc_get_report(duc, 0);
		char *canon = duc_canonicalize_path(path);
		size_t i = 0;
		struct duc_index_report *r;
		size_t best = 0;
		while ((r = duc_get_report(duc, i)) != NULL) {
			size_t l = strlen(r->path);
			if (strncmp(r->path, canon, l) == 0 && l >= best) {
				best = l;
				topn_cnt = r->topn_cnt;
			}
			duc_index_report_free(r);
			i++;
		}
		if (rep) duc_index_report_free(rep);
		free(canon);
	}

	setlocale(LC_ALL, "");
	initscr();
	cbreak();
	noecho();
	keypad(stdscr, TRUE);
	curs_set(0);

	use_color = !opt_no_color && has_colors();
	if (use_color) {
		start_color();
		init_pair(PAIR_TITLE, COLOR_WHITE, COLOR_BLUE);
		init_pair(PAIR_SEL, COLOR_BLACK, COLOR_CYAN);
		init_pair(PAIR_NORMAL, COLOR_WHITE, COLOR_BLACK);
		init_pair(PAIR_NAME, COLOR_GREEN, COLOR_BLACK);
		init_pair(PAIR_CLASS, COLOR_YELLOW, COLOR_BLACK);
		init_pair(PAIR_BAR, COLOR_CYAN, COLOR_BLACK);
	}

	int cur = 0, top = 0;

	for (;;) {
		int rows, cols;
		getmaxyx(stdscr, rows, cols);
		(void)cols;
		int page = rows - 2;
		if (page < 1) page = 1;
		int n = (int)duc_dir_get_count(dir);

		if (cur < 0) cur = 0;
		if (cur > n - 1) cur = n - 1;
		if (cur < 0) cur = 0;
		if (cur < top) top = cur;
		if (cur >= top + page) top = cur - page + 1;
		if (top < 0) top = 0;

		draw(dir, cur, top);

		int c = getch();
		switch (c) {
		case 'k': case KEY_UP: cur--; break;
		case 'j': case KEY_DOWN: cur++; break;
		case KEY_PPAGE: cur -= page; break;
		case KEY_NPAGE: cur += page; break;
		case KEY_HOME: case '0': cur = 0; break;
		case KEY_END: case '$': cur = n - 1; break;
		case 'a': opt_apparent = !opt_apparent; break;
		case 'b': opt_bytes = !opt_bytes; break;
		case 'c': opt_count = !opt_count; break;
		case 'n': opt_name_sort = !opt_name_sort; break;
		case 't': topn_mode = !topn_mode; break;
		case 'h': show_help(); break;
		case 'o': {
			struct duc_dirent *e = ent_at(dir, cur);
			if (e) {
				const char *p = duc_dir_get_path(dir);
				size_t l = strlen(p) + strlen(e->name) + 32;
				char *cmd = malloc(l);
				/* quote the path for the shell */
				size_t cl = l + 2 * (strlen(p) + strlen(e->name));
				char *q = malloc(cl);
				char *d = q;
				const char *parts[3] = { p, "/", e->name };
				for (int i = 0; i < 3; i++) {
					for (const char *s = parts[i]; *s; s++) {
						if (*s == '\'') { memcpy(d, "'\\''", 4); d += 4; }
						else *d++ = *s;
					}
				}
				*d = 0;
				snprintf(cmd, l, "xdg-open '");
				char *full = malloc(strlen(cmd) + strlen(q) + 32);
				sprintf(full, "xdg-open '%s' > /dev/null 2>&1 &", q);
				if (system(full) < 0) {}
				free(full);
				free(q);
				free(cmd);
			}
			break;
		}
		case KEY_LEFT: case KEY_BACKSPACE: case 127: case 8: {
			duc_dir *parent = duc_dir_open_parent(dir);
			if (parent) {
				struct duc_devino di = dir->devino;
				duc_dir_close(dir);
				dir = parent;
				cur = find_ent_by_devino(dir, &di);
				top = 0;
			}
			break;
		}
		case KEY_RIGHT: case '\n': case '\r': case KEY_ENTER: {
			struct duc_dirent *e = ent_at(dir, cur);
			if (e && e->type == DUC_FILE_TYPE_DIR) {
				duc_dir *child = duc_dir_openent(dir, e);
				if (child) {
					duc_dir_close(dir);
					dir = child;
					cur = 0;
					top = 0;
				}
			}
			break;
		}
		case 'q': case 27:
			goto out;
		case KEY_RESIZE:
			break;
		default:
			break;
		}
	}
out:
	endwin();
	duc_dir_close(dir);
	duc_close(duc);
	return 0;
}

