cat > /workspace/compile.sh <<'EOF'
#!/bin/sh
# Build the duc reimplementation. Requires a C compiler, sqlite3 and ncurses
# development files (libsqlite3-dev, libncurses-dev on Debian/Ubuntu).
set -e
cd "$(dirname "$0")"

need_pkg() {
	if ! pkg-config --exists "$1" 2>/dev/null && [ ! -f "/usr/include/$2" ]; then
		return 0
	fi
	return 1
}

if need_pkg sqlite3 sqlite3.h || need_pkg ncurses ncurses.h; then
	if command -v apt-get >/dev/null 2>&1; then
		apt-get install -y libsqlite3-dev libncurses-dev >/dev/null 2>&1 || \
		sudo apt-get install -y libsqlite3-dev libncurses-dev >/dev/null 2>&1 || true
	fi
fi

make -s clean >/dev/null 2>&1 || true
make -s executable
EOF
