			uint64_t h = (req->hl[i].ino * 0x9E3779B97F4A7C15ULL) ^ req->hl[i].dev;
			size_t j = h % ncap;
			while (n[j].ino != 0 || n[j].dev != 0) j = (j + 1) % ncap;
			n[j] = req->hl[i];
		}
		free(req->hl);
		req->hl = n;
		req->hl_cap = ncap;
	}
